    STMT_SEL_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS STMT_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS STMT_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS STMT_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS STMT_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS STMT_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS STMT_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS STMT_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS STMT_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS STMT_TXN_AMT_M_RDIFF 
      , ROUND(買入次數M,0) AS STMT_BUY_PROD_M 
      , ROUND(買入次數M-買入次數L,0) AS STMT_BUY_PROD_M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數L,0)>0 THEN (NVL(買入次數M,0)/NVL(買入次數L,0))-1 ELSE 0 END,4) AS STMT_BUY_PROD_M_RDIFF
      , ROUND(買入天數M,0) AS STMT_BUY_DAY_M
      , ROUND(買入天數M-買入天數L,0) AS STMT_BUY_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數L,0)>0 THEN (NVL(買入天數M,0)/NVL(買入天數L,0))-1 ELSE 0 END,4) AS STMT_BUY_DAY_M_RDIFF
      , ROUND(買入金額M,0) AS STMT_BUY_AMT_M
      , ROUND(買入金額M-買入金額L,0) AS STMT_BUY_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(買入金額L,0)>0 THEN (NVL(買入金額M,0)/NVL(買入金額L,0))-1 ELSE 0 END,4) AS STMT_BUY_AMT_M_RDIFF
      , ROUND(賣出次數M,0) AS STMT_SEL_PROD_M
      , ROUND(賣出次數M-賣出次數L,0) AS STMT_SEL_PROD_M_MDIFF 
