      , ROUND(賣出天數M,0) AS STMT_SEL_DAY_M
      , ROUND(賣出天數M-賣出天數L,0) AS STMT_SEL_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數L,0)>0 THEN (NVL(賣出天數M,0)/NVL(賣出天數L,0))-1 ELSE 0 END,4) AS STMT_SEL_DAY_M_RDIFF 
      , ROUND(賣出金額M,0) AS STMT_SEL_AMT_M 
      , ROUND(賣出金額M-賣出金額L,0) AS STMT_SEL_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(賣出金額L,0)>0 THEN (NVL(賣出金額M,0)/NVL(賣出金額L,0))-1 ELSE 0 END,4) AS STMT_SEL_AMT_M_RDIFF 
      
      , ROUND(交易次數3M,0) AS STMT_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS STMT_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS STMT_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS STMT_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS STMT_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS STMT_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS STMT_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS STMT_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS STMT_TXN_AMT_3M_RDIFF 
      , ROUND(買入次數3M,0) AS STMT_BUY_PROD_3M 
      , ROUND(買入次數3M-買入次數3ML,0) AS STMT_BUY_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數3ML,0)>0 THEN (NVL(買入次數3M,0)/NVL(買入次數3ML,0))-1 ELSE 0 END,4) AS STMT_BUY_PROD_3M_RDIFF 
      , ROUND(買入天數3M,0) AS STMT_BUY_DAY_3M 
      , ROUND(買入天數3M-買入天數3ML,0) AS STMT_BUY_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數3ML,0)>0 THEN (NVL(買入天數3M,0)/NVL(買入天數3ML,0))-1 ELSE 0 END,4) AS STMT_BUY_DAY_3M_RDIFF 
      , ROUND(買入金額3M,0) AS STMT_BUY_AMT_3M 
      , ROUND(買入金額3M-買入金額3ML,0) AS STMT_BUY_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額3ML,0)>0 THEN (NVL(買入金額3M,0)/NVL(買入金額3ML,0))-1 ELSE 0 END,4) AS STMT_BUY_AMT_3M_RDIFF 
      , ROUND(賣出次數3M,0) AS STMT_SEL_PROD_3M 
      , ROUND(賣出次數3M-賣出次數3ML,0) AS STMT_SEL_PROD_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數3ML,0)>0 THEN (NVL(賣出次數3M,0)/NVL(賣出次數3ML,0))-1 ELSE 0 END,4) AS STMT_SEL_PROD_3M_RDIFF 
      , ROUND(賣出天數3M,0) AS STMT_SEL_DAY_3M 
