      , ROUND(賣出金額3M,0) AS STMT_SEL_AMT_3M 
      , ROUND(賣出金額3M-賣出金額3ML,0) AS STMT_SEL_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額3ML,0)>0 THEN (NVL(賣出金額3M,0)/NVL(賣出金額3ML,0))-1 ELSE 0 END,4) AS STMT_SEL_AMT_3M_RDIFF 
      
      , ROUND(交易次數6M,0) AS STMT_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS STMT_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS STMT_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS STMT_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS STMT_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS STMT_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS STMT_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS STMT_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS STMT_TXN_AMT_6M_RDIFF 
      , ROUND(買入次數6M,0) AS STMT_BUY_PROD_6M 
      , ROUND(買入次數6M-買入次數6ML,0) AS STMT_BUY_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數6ML,0)>0 THEN (NVL(買入次數6M,0)/NVL(買入次數6ML,0))-1 ELSE 0 END,4) AS STMT_BUY_PROD_6M_RDIFF 
      , ROUND(買入天數6M,0) AS STMT_BUY_DAY_6M 
      , ROUND(買入天數6M-買入天數6ML,0) AS STMT_BUY_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數6ML,0)>0 THEN (NVL(買入天數6M,0)/NVL(買入天數6ML,0))-1 ELSE 0 END,4) AS STMT_BUY_DAY_6M_RDIFF 
      , ROUND(買入金額6M,0) AS STMT_BUY_AMT_6M 
      , ROUND(買入金額6M-買入金額6ML,0) AS STMT_BUY_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額6ML,0)>0 THEN (NVL(買入金額6M,0)/NVL(買入金額6ML,0))-1 ELSE 0 END,4) AS STMT_BUY_AMT_6M_RDIFF 
      , ROUND(賣出次數6M,0) AS STMT_SEL_PROD_6M 
      , ROUND(賣出次數6M-賣出次數6ML,0) AS STMT_SEL_PROD_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數6ML,0)>0 THEN (NVL(賣出次數6M,0)/NVL(賣出次數6ML,0))-1 ELSE 0 END,4) AS STMT_SEL_PROD_6M_RDIFF 
      , ROUND(賣出天數6M,0) AS STMT_SEL_DAY_6M 
