      , ROUND(CASE WHEN NVL(賣出天數6ML,0)>0 THEN (NVL(賣出天數6M,0)/NVL(賣出天數6ML,0))-1 ELSE 0 END,4) AS STMT_SEL_DAY_6M_RDIFF 
      , ROUND(賣出金額6M,0) AS STMT_SEL_AMT_6M 
