      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS STMT_TXN_PROD_12M_RDIFF 
