      , ROUND(交易天數12M-交易天數12ML,0) AS STMT_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS STMT_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS STMT_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS STMT_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS STMT_TXN_AMT_12M_RDIFF 
      , ROUND(買入次數12M,0) AS STMT_BUY_PROD_12M 
      , ROUND(買入次數12M-買入次數12ML,0) AS STMT_BUY_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數12ML,0)>0 THEN (NVL(買入次數12M,0)/NVL(買入次數12ML,0))-1 ELSE 0 END,4) AS STMT_BUY_PROD_12M_RDIFF 
      , ROUND(買入天數12M,0) AS STMT_BUY_DAY_12M 
