      , ROUND(賣出金額12M-賣出金額12ML,0) AS STMT_SEL_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額12ML,0)>0 THEN (NVL(賣出金額12M,0)/NVL(賣出金額12ML,0))-1 ELSE 0 END,4) AS STMT_SEL_AMT_12M_RDIFF 
FROM TEMPSTMT2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_台股融券-----------------------------------------------
INSERT INTO DS_SEC.CF_TXN_STSS
WITH TEMPSTSS1
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '001' THEN TXN_DATE ELSE NULL END) AS 買入天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN 1 ELSE 0 END) AS 買入次數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END) AS 買入金額
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '002' THEN TXN_DATE ELSE NULL END) AS 賣出天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN 1 ELSE 0 END) AS 賣出次數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END) AS 賣出金額
FROM DM_S_VIEW.M_AT_STOCK_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_TYPE_DETAIL_CODE IN ('006','008') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), TEMPSTSS2
AS (
SELECT CUSTOMER_ID
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END)交易次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END)交易天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END)交易金額M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 買入次數 ELSE 0 END)買入次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 買入天數 ELSE 0 END)買入天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 買入金額 ELSE 0 END)買入金額M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 賣出次數 ELSE 0 END)賣出次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 賣出天數 ELSE 0 END)賣出天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 賣出金額 ELSE 0 END)賣出金額M
      
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額L
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END)買入次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END)買入天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END)買入金額3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END)賣出次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END)賣出天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END)賣出金額3M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額3ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END)買入次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END)買入天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END)買入金額6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END)賣出次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END)賣出天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END)賣出金額6M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額6ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END)買入次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END)買入天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END)買入金額12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END)賣出次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END)賣出天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END)賣出金額12M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額12ML
FROM TEMPSTSS1
GROUP BY CUSTOMER_ID
)

