    STSS_SEL_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS STSS_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS STSS_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS STSS_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS STSS_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS STSS_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS STSS_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS STSS_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS STSS_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS STSS_TXN_AMT_M_RDIFF 
      , ROUND(買入次數M,0) AS STSS_BUY_PROD_M 
      , ROUND(買入次數M-買入次數L,0) AS STSS_BUY_PROD_M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數L,0)>0 THEN (NVL(買入次數M,0)/NVL(買入次數L,0))-1 ELSE 0 END,4) AS STSS_BUY_PROD_M_RDIFF
      , ROUND(買入天數M,0) AS STSS_BUY_DAY_M
      , ROUND(買入天數M-買入天數L,0) AS STSS_BUY_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數L,0)>0 THEN (NVL(買入天數M,0)/NVL(買入天數L,0))-1 ELSE 0 END,4) AS STSS_BUY_DAY_M_RDIFF
      , ROUND(買入金額M,0) AS STSS_BUY_AMT_M
      , ROUND(買入金額M-買入金額L,0) AS STSS_BUY_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(買入金額L,0)>0 THEN (NVL(買入金額M,0)/NVL(買入金額L,0))-1 ELSE 0 END,4) AS STSS_BUY_AMT_M_RDIFF
      , ROUND(賣出次數M,0) AS STSS_SEL_PROD_M
      , ROUND(賣出次數M-賣出次數L,0) AS STSS_SEL_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數L,0)>0 THEN (NVL(賣出次數M,0)/NVL(賣出次數L,0))-1 ELSE 0 END,4) AS STSS_SEL_PROD_M_RDIFF 
      , ROUND(賣出天數M,0) AS STSS_SEL_DAY_M
      , ROUND(賣出天數M-賣出天數L,0) AS STSS_SEL_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數L,0)>0 THEN (NVL(賣出天數M,0)/NVL(賣出天數L,0))-1 ELSE 0 END,4) AS STSS_SEL_DAY_M_RDIFF 
      , ROUND(賣出金額M,0) AS STSS_SEL_AMT_M 
      , ROUND(賣出金額M-賣出金額L,0) AS STSS_SEL_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(賣出金額L,0)>0 THEN (NVL(賣出金額M,0)/NVL(賣出金額L,0))-1 ELSE 0 END,4) AS STSS_SEL_AMT_M_RDIFF 
      
      , ROUND(交易次數3M,0) AS STSS_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS STSS_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS STSS_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS STSS_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS STSS_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS STSS_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS STSS_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS STSS_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS STSS_TXN_AMT_3M_RDIFF 
      , ROUND(買入次數3M,0) AS STSS_BUY_PROD_3M 
      , ROUND(買入次數3M-買入次數3ML,0) AS STSS_BUY_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數3ML,0)>0 THEN (NVL(買入次數3M,0)/NVL(買入次數3ML,0))-1 ELSE 0 END,4) AS STSS_BUY_PROD_3M_RDIFF 
      , ROUND(買入天數3M,0) AS STSS_BUY_DAY_3M 
      , ROUND(買入天數3M-買入天數3ML,0) AS STSS_BUY_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數3ML,0)>0 THEN (NVL(買入天數3M,0)/NVL(買入天數3ML,0))-1 ELSE 0 END,4) AS STSS_BUY_DAY_3M_RDIFF 
      , ROUND(買入金額3M,0) AS STSS_BUY_AMT_3M 
      , ROUND(買入金額3M-買入金額3ML,0) AS STSS_BUY_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額3ML,0)>0 THEN (NVL(買入金額3M,0)/NVL(買入金額3ML,0))-1 ELSE 0 END,4) AS STSS_BUY_AMT_3M_RDIFF 
      , ROUND(賣出次數3M,0) AS STSS_SEL_PROD_3M 
      , ROUND(賣出次數3M-賣出次數3ML,0) AS STSS_SEL_PROD_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數3ML,0)>0 THEN (NVL(賣出次數3M,0)/NVL(賣出次數3ML,0))-1 ELSE 0 END,4) AS STSS_SEL_PROD_3M_RDIFF 
      , ROUND(賣出天數3M,0) AS STSS_SEL_DAY_3M 
      , ROUND(賣出天數3M-賣出天數3ML,0) AS STSS_SEL_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數3ML,0)>0 THEN (NVL(賣出天數3M,0)/NVL(賣出天數3ML,0))-1 ELSE 0 END,4) AS STSS_SEL_DAY_3M_RDIFF 
      , ROUND(賣出金額3M,0) AS STSS_SEL_AMT_3M 
      , ROUND(賣出金額3M-賣出金額3ML,0) AS STSS_SEL_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額3ML,0)>0 THEN (NVL(賣出金額3M,0)/NVL(賣出金額3ML,0))-1 ELSE 0 END,4) AS STSS_SEL_AMT_3M_RDIFF 
      
      , ROUND(交易次數6M,0) AS STSS_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS STSS_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS STSS_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS STSS_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS STSS_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS STSS_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS STSS_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS STSS_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS STSS_TXN_AMT_6M_RDIFF 
      , ROUND(買入次數6M,0) AS STSS_BUY_PROD_6M 
      , ROUND(買入次數6M-買入次數6ML,0) AS STSS_BUY_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數6ML,0)>0 THEN (NVL(買入次數6M,0)/NVL(買入次數6ML,0))-1 ELSE 0 END,4) AS STSS_BUY_PROD_6M_RDIFF 
      , ROUND(買入天數6M,0) AS STSS_BUY_DAY_6M 
      , ROUND(買入天數6M-買入天數6ML,0) AS STSS_BUY_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數6ML,0)>0 THEN (NVL(買入天數6M,0)/NVL(買入天數6ML,0))-1 ELSE 0 END,4) AS STSS_BUY_DAY_6M_RDIFF 
      , ROUND(買入金額6M,0) AS STSS_BUY_AMT_6M 
      , ROUND(買入金額6M-買入金額6ML,0) AS STSS_BUY_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額6ML,0)>0 THEN (NVL(買入金額6M,0)/NVL(買入金額6ML,0))-1 ELSE 0 END,4) AS STSS_BUY_AMT_6M_RDIFF 
      , ROUND(賣出次數6M,0) AS STSS_SEL_PROD_6M 
      , ROUND(賣出次數6M-賣出次數6ML,0) AS STSS_SEL_PROD_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數6ML,0)>0 THEN (NVL(賣出次數6M,0)/NVL(賣出次數6ML,0))-1 ELSE 0 END,4) AS STSS_SEL_PROD_6M_RDIFF 
      , ROUND(賣出天數6M,0) AS STSS_SEL_DAY_6M 
      , ROUND(賣出天數6M-賣出天數6ML,0) AS STSS_SEL_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數6ML,0)>0 THEN (NVL(賣出天數6M,0)/NVL(賣出天數6ML,0))-1 ELSE 0 END,4) AS STSS_SEL_DAY_6M_RDIFF 
      , ROUND(賣出金額6M,0) AS STSS_SEL_AMT_6M 
      , ROUND(賣出金額6M-賣出金額6ML,0) AS STSS_SEL_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額6ML,0)>0 THEN (NVL(賣出金額6M,0)/NVL(賣出金額6ML,0))-1 ELSE 0 END,4) AS STSS_SEL_AMT_6M_RDIFF 
      
      , ROUND(交易次數12M,0) AS STSS_TXN_PROD_12M 
      , ROUND(交易次數12M-交易次數12ML,0) AS STSS_TXN_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS STSS_TXN_PROD_12M_RDIFF 
      , ROUND(交易天數12M,0) AS STSS_TXN_DAY_12M 
      , ROUND(交易天數12M-交易天數12ML,0) AS STSS_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS STSS_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS STSS_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS STSS_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS STSS_TXN_AMT_12M_RDIFF 
      , ROUND(買入次數12M,0) AS STSS_BUY_PROD_12M 
      , ROUND(買入次數12M-買入次數12ML,0) AS STSS_BUY_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數12ML,0)>0 THEN (NVL(買入次數12M,0)/NVL(買入次數12ML,0))-1 ELSE 0 END,4) AS STSS_BUY_PROD_12M_RDIFF 
      , ROUND(買入天數12M,0) AS STSS_BUY_DAY_12M 
      , ROUND(買入天數12M-買入天數12ML,0) AS STSS_BUY_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數12ML,0)>0 THEN (NVL(買入天數12M,0)/NVL(買入天數12ML,0))-1 ELSE 0 END,4) AS STSS_BUY_DAY_12M_RDIFF 
      , ROUND(買入金額12M,0) AS STSS_BUY_AMT_12M 
      , ROUND(買入金額12M-買入金額12ML,0) AS STSS_BUY_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額12ML,0)>0 THEN (NVL(買入金額12M,0)/NVL(買入金額12ML,0))-1 ELSE 0 END,4) AS STSS_BUY_AMT_12M_RDIFF 
      , ROUND(賣出次數12M,0) AS STSS_SEL_PROD_12M 
      , ROUND(賣出次數12M-賣出次數12ML,0) AS STSS_SEL_PROD_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數12ML,0)>0 THEN (NVL(賣出次數12M,0)/NVL(賣出次數12ML,0))-1 ELSE 0 END,4) AS STSS_SEL_PROD_12M_RDIFF 
      , ROUND(賣出天數12M,0) AS STSS_SEL_DAY_12M 
      , ROUND(賣出天數12M-賣出天數12ML,0) AS STSS_SEL_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數12ML,0)>0 THEN (NVL(賣出天數12M,0)/NVL(賣出天數12ML,0))-1 ELSE 0 END,4) AS STSS_SEL_DAY_12M_RDIFF 
      , ROUND(賣出金額12M,0) AS STSS_SEL_AMT_12M 
      , ROUND(賣出金額12M-賣出金額12ML,0) AS STSS_SEL_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額12ML,0)>0 THEN (NVL(賣出金額12M,0)/NVL(賣出金額12ML,0))-1 ELSE 0 END,4) AS STSS_SEL_AMT_12M_RDIFF 
FROM TEMPSTSS2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_台股定期定額-------------------------------------------
INSERT INTO DS_SEC.CF_TXN_SIP
WITH TEMPSIP1
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
FROM DM_S_VIEW.M_AT_STOCK_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_TYPE_CODE = '102' AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), TEMPSIP2
AS (
SELECT CUSTOMER_ID
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END)交易次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END)交易天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END)交易金額M
      
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額L
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額3M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額3ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額6M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額6ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額12M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額12ML
FROM TEMPSIP1
GROUP BY CUSTOMER_ID
)
SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    SIP_TXN_PROD_M,
    SIP_TXN_PROD_M_MDIFF,
    SIP_TXN_PROD_M_RDIFF,
    SIP_TXN_DAY_M,
    SIP_TXN_DAY_M_MDIFF,
    SIP_TXN_DAY_M_RDIFF,
    SIP_TXN_AMT_M,
    SIP_TXN_AMT_M_MDIFF,
    SIP_TXN_AMT_M_RDIFF,
    SIP_TXN_PROD_3M,
    SIP_TXN_PROD_3M_MDIFF,
    SIP_TXN_PROD_3M_RDIFF,
    SIP_TXN_DAY_3M,
    SIP_TXN_DAY_3M_MDIFF,
    SIP_TXN_DAY_3M_RDIFF,
    SIP_TXN_AMT_3M,
    SIP_TXN_AMT_3M_MDIFF,
    SIP_TXN_AMT_3M_RDIFF,
    SIP_TXN_PROD_6M,
    SIP_TXN_PROD_6M_MDIFF,
    SIP_TXN_PROD_6M_RDIFF,
    SIP_TXN_DAY_6M,
    SIP_TXN_DAY_6M_MDIFF,
    SIP_TXN_DAY_6M_RDIFF,
    SIP_TXN_AMT_6M,
    SIP_TXN_AMT_6M_MDIFF,
    SIP_TXN_AMT_6M_RDIFF,
    SIP_TXN_PROD_12M,
    SIP_TXN_PROD_12M_MDIFF,
    SIP_TXN_PROD_12M_RDIFF,
    SIP_TXN_DAY_12M,
    SIP_TXN_DAY_12M_MDIFF,
    SIP_TXN_DAY_12M_RDIFF,
    SIP_TXN_AMT_12M,
    SIP_TXN_AMT_12M_MDIFF,
    SIP_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS SIP_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS SIP_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS SIP_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS SIP_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS SIP_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS SIP_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS SIP_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS SIP_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS SIP_TXN_AMT_M_RDIFF 
      
      , ROUND(交易次數3M,0) AS SIP_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS SIP_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS SIP_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS SIP_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS SIP_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS SIP_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS SIP_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS SIP_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS SIP_TXN_AMT_3M_RDIFF 
      
      , ROUND(交易次數6M,0) AS SIP_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS SIP_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS SIP_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS SIP_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS SIP_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS SIP_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS SIP_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS SIP_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS SIP_TXN_AMT_6M_RDIFF
      
      , ROUND(交易次數12M,0) AS SIP_TXN_PROD_12M 
      , ROUND(交易次數12M-交易次數12ML,0) AS SIP_TXN_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS SIP_TXN_PROD_12M_RDIFF 
      , ROUND(交易天數12M,0) AS SIP_TXN_DAY_12M 
      , ROUND(交易天數12M-交易天數12ML,0) AS SIP_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS SIP_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS SIP_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS SIP_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS SIP_TXN_AMT_12M_RDIFF
FROM TEMPSIP2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_台股當沖-----------------------------------------------
INSERT INTO DS_SEC.CF_TXN_STDT
WITH TEMPSTDT1
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
FROM DM_S_VIEW.M_AT_STOCK_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_TYPE_DETAIL_CODE IN('001','005','006') AND TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), TEMPSTDT2
AS (
SELECT CUSTOMER_ID
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END)交易次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END)交易天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END)交易金額M
      
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額L
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額3M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額3ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額6M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額6ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額12M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額12ML
FROM TEMPSTDT1
GROUP BY CUSTOMER_ID
)

SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    STDT_TXN_PROD_M,
    STDT_TXN_PROD_M_MDIFF,
    STDT_TXN_PROD_M_RDIFF,
    STDT_TXN_DAY_M,
    STDT_TXN_DAY_M_MDIFF,
    STDT_TXN_DAY_M_RDIFF,
    STDT_TXN_AMT_M,
    STDT_TXN_AMT_M_MDIFF,
    STDT_TXN_AMT_M_RDIFF,
    STDT_TXN_PROD_3M,
    STDT_TXN_PROD_3M_MDIFF,
    STDT_TXN_PROD_3M_RDIFF,
    STDT_TXN_DAY_3M,
    STDT_TXN_DAY_3M_MDIFF,
    STDT_TXN_DAY_3M_RDIFF,
    STDT_TXN_AMT_3M,
    STDT_TXN_AMT_3M_MDIFF,
    STDT_TXN_AMT_3M_RDIFF,
    STDT_TXN_PROD_6M,
    STDT_TXN_PROD_6M_MDIFF,
    STDT_TXN_PROD_6M_RDIFF,
    STDT_TXN_DAY_6M,
    STDT_TXN_DAY_6M_MDIFF,
    STDT_TXN_DAY_6M_RDIFF,
    STDT_TXN_AMT_6M,
    STDT_TXN_AMT_6M_MDIFF,
    STDT_TXN_AMT_6M_RDIFF,
    STDT_TXN_PROD_12M,
    STDT_TXN_PROD_12M_MDIFF,
    STDT_TXN_PROD_12M_RDIFF,
    STDT_TXN_DAY_12M,
    STDT_TXN_DAY_12M_MDIFF,
    STDT_TXN_DAY_12M_RDIFF,
    STDT_TXN_AMT_12M,
    STDT_TXN_AMT_12M_MDIFF,
    STDT_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS STDT_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS STDT_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS STDT_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS STDT_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS STDT_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS STDT_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS STDT_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS STDT_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS STDT_TXN_AMT_M_RDIFF  
      
      , ROUND(交易次數3M,0) AS STDT_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS STDT_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS STDT_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS STDT_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS STDT_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS STDT_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS STDT_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS STDT_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS STDT_TXN_AMT_3M_RDIFF
      
      , ROUND(交易次數6M,0) AS STDT_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS STDT_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS STDT_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS STDT_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS STDT_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS STDT_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS STDT_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS STDT_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS STDT_TXN_AMT_6M_RDIFF
      
      , ROUND(交易次數12M,0) AS STDT_TXN_PROD_12M 
      , ROUND(交易次數12M-交易次數12ML,0) AS STDT_TXN_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS STDT_TXN_PROD_12M_RDIFF 
      , ROUND(交易天數12M,0) AS STDT_TXN_DAY_12M 
      , ROUND(交易天數12M-交易天數12ML,0) AS STDT_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS STDT_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS STDT_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS STDT_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS STDT_TXN_AMT_12M_RDIFF 
FROM TEMPSTDT2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_不限用途-----------------------------------------------
INSERT INTO DS_SEC.CF_TXN_LOAN
WITH TEMPLOAN1
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
FROM DM_S_VIEW.M_AT_LOAN_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), TEMPLOAN2
AS (
SELECT CUSTOMER_ID
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END)交易次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END)交易天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END)交易金額M
      
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額L
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額3M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額3ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額6M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額6ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額12M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額12ML
FROM TEMPLOAN1
GROUP BY CUSTOMER_ID

)
SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    LOAN_TXN_PROD_M,
    LOAN_TXN_PROD_M_MDIFF,
    LOAN_TXN_PROD_M_RDIFF,
    LOAN_TXN_DAY_M,
    LOAN_TXN_DAY_M_MDIFF,
    LOAN_TXN_DAY_M_RDIFF,
    LOAN_TXN_AMT_M,
    LOAN_TXN_AMT_M_MDIFF,
    LOAN_TXN_AMT_M_RDIFF,
    LOAN_TXN_PROD_3M,
    LOAN_TXN_PROD_3M_MDIFF,
    LOAN_TXN_PROD_3M_RDIFF,
    LOAN_TXN_DAY_3M,
    LOAN_TXN_DAY_3M_MDIFF,
    LOAN_TXN_DAY_3M_RDIFF,
    LOAN_TXN_AMT_3M,
    LOAN_TXN_AMT_3M_MDIFF,
    LOAN_TXN_AMT_3M_RDIFF,
    LOAN_TXN_PROD_6M,
    LOAN_TXN_PROD_6M_MDIFF,
    LOAN_TXN_PROD_6M_RDIFF,
    LOAN_TXN_DAY_6M,
    LOAN_TXN_DAY_6M_MDIFF,
    LOAN_TXN_DAY_6M_RDIFF,
    LOAN_TXN_AMT_6M,
    LOAN_TXN_AMT_6M_MDIFF,
    LOAN_TXN_AMT_6M_RDIFF,
    LOAN_TXN_PROD_12M,
    LOAN_TXN_PROD_12M_MDIFF,
    LOAN_TXN_PROD_12M_RDIFF,
    LOAN_TXN_DAY_12M,
    LOAN_TXN_DAY_12M_MDIFF,
    LOAN_TXN_DAY_12M_RDIFF,
    LOAN_TXN_AMT_12M,
    LOAN_TXN_AMT_12M_MDIFF,
    LOAN_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS LOAN_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS LOAN_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS LOAN_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS LOAN_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS LOAN_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS LOAN_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS LOAN_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS LOAN_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS LOAN_TXN_AMT_M_RDIFF  
      
      , ROUND(交易次數3M,0) AS LOAN_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS LOAN_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS LOAN_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS LOAN_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS LOAN_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS LOAN_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_AMT_3M_RDIFF
      
      , ROUND(交易次數6M,0) AS LOAN_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS LOAN_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS LOAN_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS LOAN_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS LOAN_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS LOAN_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_AMT_6M_RDIFF
      
      , ROUND(交易次數12M,0) AS LOAN_TXN_PROD_12M 
      , ROUND(交易次數12M-交易次數12ML,0) AS LOAN_TXN_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_PROD_12M_RDIFF 
      , ROUND(交易天數12M,0) AS LOAN_TXN_DAY_12M 
      , ROUND(交易天數12M-交易天數12ML,0) AS LOAN_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS LOAN_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS LOAN_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS LOAN_TXN_AMT_12M_RDIFF 
FROM TEMPLOAN2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID
;
----------------------------------交易_雙向借券-----------------------------------------------
INSERT INTO DS_SEC.CF_TXN_BSBL
WITH TEMPBSBL1
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
FROM DM_S_VIEW.M_AT_BSBL_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), TEMPBSBL2
AS (
SELECT CUSTOMER_ID
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END)交易次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END)交易天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END)交易金額M
      
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額L
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額3M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額3ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額6M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額6ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額12M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額12ML
FROM TEMPBSBL1
GROUP BY CUSTOMER_ID

) 
SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    BSBL_TXN_PROD_M,
    BSBL_TXN_PROD_M_MDIFF,
    BSBL_TXN_PROD_M_RDIFF,
    BSBL_TXN_DAY_M,
    BSBL_TXN_DAY_M_MDIFF,
    BSBL_TXN_DAY_M_RDIFF,
    BSBL_TXN_AMT_M,
    BSBL_TXN_AMT_M_MDIFF,
    BSBL_TXN_AMT_M_RDIFF,
    BSBL_TXN_PROD_3M,
    BSBL_TXN_PROD_3M_MDIFF,
    BSBL_TXN_PROD_3M_RDIFF,
    BSBL_TXN_DAY_3M,
    BSBL_TXN_DAY_3M_MDIFF,
    BSBL_TXN_DAY_3M_RDIFF,
    BSBL_TXN_AMT_3M,
    BSBL_TXN_AMT_3M_MDIFF,
    BSBL_TXN_AMT_3M_RDIFF,
    BSBL_TXN_PROD_6M,
    BSBL_TXN_PROD_6M_MDIFF,
    BSBL_TXN_PROD_6M_RDIFF,
    BSBL_TXN_DAY_6M,
    BSBL_TXN_DAY_6M_MDIFF,
    BSBL_TXN_DAY_6M_RDIFF,
    BSBL_TXN_AMT_6M,
    BSBL_TXN_AMT_6M_MDIFF,
    BSBL_TXN_AMT_6M_RDIFF,
    BSBL_TXN_PROD_12M,
    BSBL_TXN_PROD_12M_MDIFF,
    BSBL_TXN_PROD_12M_RDIFF,
    BSBL_TXN_DAY_12M,
    BSBL_TXN_DAY_12M_MDIFF,
    BSBL_TXN_DAY_12M_RDIFF,
    BSBL_TXN_AMT_12M,
    BSBL_TXN_AMT_12M_MDIFF,
    BSBL_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS BSBL_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS BSBL_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS BSBL_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS BSBL_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS BSBL_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS BSBL_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS BSBL_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS BSBL_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS BSBL_TXN_AMT_M_RDIFF  
      
      , ROUND(交易次數3M,0) AS BSBL_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS BSBL_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS BSBL_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS BSBL_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS BSBL_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS BSBL_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_AMT_3M_RDIFF
      
      , ROUND(交易次數6M,0) AS BSBL_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS BSBL_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS BSBL_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS BSBL_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS BSBL_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS BSBL_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_AMT_6M_RDIFF
      
      , ROUND(交易次數12M,0) AS BSBL_TXN_PROD_12M 
      , ROUND(交易次數12M-交易次數12ML,0) AS BSBL_TXN_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_PROD_12M_RDIFF 
      , ROUND(交易天數12M,0) AS BSBL_TXN_DAY_12M 
      , ROUND(交易天數12M-交易天數12ML,0) AS BSBL_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS BSBL_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS BSBL_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS BSBL_TXN_AMT_12M_RDIFF 
FROM TEMPBSBL2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID
;
----------------------------------交易_期權---------------------------------------------------
INSERT INTO DS_SEC.CF_TXN_FU
WITH TEMPFU1
AS (
SELECT PARTY_ID_MASK CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_UNIT_QTY)AS 交易口數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN 1 ELSE 0 END) AS 買入次數
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '001' THEN TXN_DATE ELSE NULL END) AS 買入天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN TXN_UNIT_QTY ELSE 0 END) AS 買入口數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN 1 ELSE 0 END) AS 賣出次數
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '002' THEN TXN_DATE ELSE NULL END) AS 賣出天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN TXN_UNIT_QTY ELSE 0 END) AS 賣出口數
FROM DM_S_VIEW.M_AT_FUTURE_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), 
TEMPFU2 AS (
SELECT CUSTOMER_ID,
      :ym AS YYYYMM,
      SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END) AS 交易次數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END) AS 交易天數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 交易口數 ELSE 0 END) AS 交易口數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 買入次數 ELSE 0 END) AS 買入次數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 買入天數 ELSE 0 END) AS 買入天數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 買入口數 ELSE 0 END) AS 買入口數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_M,
      SUM(CASE WHEN YYYYMM = :ym THEN 賣出口數 ELSE 0 END) AS 賣出口數_M,

      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易口數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入口數 ELSE 0 END) AS 買入口數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_ML,
      SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出口數 ELSE 0 END) AS 賣出口數_ML,

      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易口數 ELSE 0 END) AS 交易口數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入口數 ELSE 0 END) AS 買入口數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_3M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出口數 ELSE 0 END) AS 賣出口數_3M,

      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易口數 ELSE 0 END) AS 交易口數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入口數 ELSE 0 END) AS 買入口數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_3ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出口數 ELSE 0 END) AS 賣出口數_3ML,

      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易口數 ELSE 0 END) AS 交易口數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入口數 ELSE 0 END) AS 買入口數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_6M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出口數 ELSE 0 END) AS 賣出口數_6M,

      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易口數 ELSE 0 END) AS 交易口數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入口數 ELSE 0 END) AS 買入口數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_6ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出口數 ELSE 0 END) AS 賣出口數_6ML,

      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易口數 ELSE 0 END) AS 交易口數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入口數 ELSE 0 END) AS 買入口數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_12M,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出口數 ELSE 0 END) AS 賣出口數_12M,

      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易口數 ELSE 0 END) AS 交易口數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入口數 ELSE 0 END) AS 買入口數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_12ML,
      SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出口數 ELSE 0 END) AS 賣出口數_12ML
FROM TEMPFU1
GROUP BY CUSTOMER_ID
)
SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    FU_TXN_PROD_M,
    FU_TXN_DAY_M,
    FU_TXN_AMT_M,
    FU_BUY_PROD_M,
    FU_BUY_DAY_M,
    FU_BUY_AMT_M,
    FU_SEL_PROD_M,
    FU_SEL_DAY_M,
    FU_SEL_AMT_M,
    FU_TXN_PROD_3M,
    FU_TXN_DAY_3M,
    FU_TXN_AMT_3M,
    FU_BUY_PROD_3M,
    FU_BUY_DAY_3M,
    FU_BUY_AMT_3M,
    FU_SEL_PROD_3M,
    FU_SEL_DAY_3M,
    FU_SEL_AMT_3M,
    FU_TXN_PROD_6M,
    FU_TXN_DAY_6M,
    FU_TXN_AMT_6M,
    FU_BUY_PROD_6M,
    FU_BUY_DAY_6M,
    FU_BUY_AMT_6M,
    FU_SEL_PROD_6M,
    FU_SEL_DAY_6M,
    FU_SEL_AMT_6M,
    FU_TXN_PROD_12M,
    FU_TXN_DAY_12M,
    FU_TXN_AMT_12M,
    FU_BUY_PROD_12M,
    FU_BUY_DAY_12M,
    FU_BUY_AMT_12M,
    FU_SEL_PROD_12M,
    FU_SEL_DAY_12M,
    FU_SEL_AMT_12M,
    FU_TXN_PROD_M_MDIFF,
    FU_TXN_DAY_M_MDIFF,
    FU_TXN_AMT_M_MDIFF,
    FU_BUY_PROD_M_MDIFF,
    FU_BUY_DAY_M_MDIFF,
    FU_BUY_AMT_M_MDIFF,
    FU_SEL_PROD_M_MDIFF,
    FU_SEL_DAY_M_MDIFF,
    FU_SEL_AMT_M_MDIFF,
    FU_TXN_PROD_M_RDIFF,
    FU_TXN_DAY_M_RDIFF,
    FU_TXN_AMT_M_RDIFF,
    FU_BUY_PROD_M_RDIFF,
    FU_BUY_DAY_M_RDIFF,
    FU_BUY_AMT_M_RDIFF,
    FU_SEL_PROD_M_RDIFF,
    FU_SEL_DAY_M_RDIFF,
    FU_SEL_AMT_M_RDIFF,
    FU_TXN_PROD_3M_MDIFF,
    FU_TXN_DAY_3M_MDIFF,
    FU_TXN_AMT_3M_MDIFF,
    FU_BUY_PROD_3M_MDIFF,
    FU_BUY_DAY_3M_MDIFF,
    FU_BUY_AMT_3M_MDIFF,
    FU_SEL_PROD_3M_MDIFF,
    FU_SEL_DAY_3M_MDIFF,
    FU_SEL_AMT_3M_MDIFF,
    FU_TXN_PROD_3M_RDIFF,
    FU_TXN_DAY_3M_RDIFF,
    FU_TXN_AMT_3M_RDIFF,
    FU_BUY_PROD_3M_RDIFF,
    FU_BUY_DAY_3M_RDIFF,
    FU_BUY_AMT_3M_RDIFF,
    FU_SEL_PROD_3M_RDIFF,
    FU_SEL_DAY_3M_RDIFF,
    FU_SEL_AMT_3M_RDIFF,
    FU_TXN_PROD_6M_MDIFF,
    FU_TXN_DAY_6M_MDIFF,
    FU_TXN_AMT_6M_MDIFF,
    FU_BUY_PROD_6M_MDIFF,
    FU_BUY_DAY_6M_MDIFF,
    FU_BUY_AMT_6M_MDIFF,
    FU_SEL_PROD_6M_MDIFF,
    FU_SEL_DAY_6M_MDIFF,
    FU_SEL_AMT_6M_MDIFF,
    FU_TXN_PROD_6M_RDIFF,
    FU_TXN_DAY_6M_RDIFF,
    FU_TXN_AMT_6M_RDIFF,
    FU_BUY_PROD_6M_RDIFF,
    FU_BUY_DAY_6M_RDIFF,
    FU_BUY_AMT_6M_RDIFF,
    FU_SEL_PROD_6M_RDIFF,
    FU_SEL_DAY_6M_RDIFF,
    FU_SEL_AMT_6M_RDIFF,
    FU_TXN_PROD_12M_MDIFF,
    FU_TXN_DAY_12M_MDIFF,
    FU_TXN_AMT_12M_MDIFF,
    FU_BUY_PROD_12M_MDIFF,
    FU_BUY_DAY_12M_MDIFF,
    FU_BUY_AMT_12M_MDIFF,
    FU_SEL_PROD_12M_MDIFF,
    FU_SEL_DAY_12M_MDIFF,
    FU_SEL_AMT_12M_MDIFF,
    FU_TXN_PROD_12M_RDIFF,
    FU_TXN_DAY_12M_RDIFF,
    FU_TXN_AMT_12M_RDIFF,
    FU_BUY_PROD_12M_RDIFF,
    FU_BUY_DAY_12M_RDIFF,
    FU_BUY_AMT_12M_RDIFF,
    FU_SEL_PROD_12M_RDIFF,
    FU_SEL_DAY_12M_RDIFF,
    FU_SEL_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
SELECT CUSTOMER_ID,
    YYYYMM,
    round(交易次數_M,0) AS FU_TXN_PROD_M,
    round(交易天數_M,0) AS FU_TXN_DAY_M,
    round(交易口數_M,0) AS FU_TXN_AMT_M,
    round(買入次數_M,0) AS FU_BUY_PROD_M,
    round(買入天數_M,0) AS FU_BUY_DAY_M,
    round(買入口數_M,0) AS FU_BUY_AMT_M,
    round(賣出次數_M,0) AS FU_SEL_PROD_M,
    round(賣出天數_M,0) AS FU_SEL_DAY_M,
    round(賣出口數_M,0) AS FU_SEL_AMT_M,
    round(交易次數_ML,0) AS FU_TXN_PROD_ML,
    round(交易天數_ML,0) AS FU_TXN_DAY_ML,
    round(交易口數_ML,0) AS FU_TXN_AMT_ML,
    round(買入次數_ML,0) AS FU_BUY_PROD_ML,
    round(買入天數_ML,0) AS FU_BUY_DAY_ML,
    round(買入口數_ML,0) AS FU_BUY_AMT_ML,
    round(賣出次數_ML,0) AS FU_SEL_PROD_ML,
    round(賣出天數_ML,0) AS FU_SEL_DAY_ML,
    round(賣出口數_ML,0) AS FU_SEL_AMT_ML,
    round(交易次數_3M,0) AS FU_TXN_PROD_3M,
    round(交易天數_3M,0) AS FU_TXN_DAY_3M,
    round(交易口數_3M,0) AS FU_TXN_AMT_3M,
    round(買入次數_3M,0) AS FU_BUY_PROD_3M,
    round(買入天數_3M,0) AS FU_BUY_DAY_3M,
    round(買入口數_3M,0) AS FU_BUY_AMT_3M,
    round(賣出次數_3M,0) AS FU_SEL_PROD_3M,
    round(賣出天數_3M,0) AS FU_SEL_DAY_3M,
    round(賣出口數_3M,0) AS FU_SEL_AMT_3M,
    round(交易次數_3ML,0) AS FU_TXN_PROD_3ML,
    round(交易天數_3ML,0) AS FU_TXN_DAY_3ML,
    round(交易口數_3ML,0) AS FU_TXN_AMT_3ML,
    round(買入次數_3ML,0) AS FU_BUY_PROD_3ML,
    round(買入天數_3ML,0) AS FU_BUY_DAY_3ML,
    round(買入口數_3ML,0) AS FU_BUY_AMT_3ML,
    round(賣出次數_3ML,0) AS FU_SEL_PROD_3ML,
    round(賣出天數_3ML,0) AS FU_SEL_DAY_3ML,
    round(賣出口數_3ML,0) AS FU_SEL_AMT_3ML,
    round(交易次數_6M,0) AS FU_TXN_PROD_6M,
    round(交易天數_6M,0) AS FU_TXN_DAY_6M,
    round(交易口數_6M,0) AS FU_TXN_AMT_6M,
    round(買入次數_6M,0) AS FU_BUY_PROD_6M,
    round(買入天數_6M,0) AS FU_BUY_DAY_6M,
    round(買入口數_6M,0) AS FU_BUY_AMT_6M,
    round(賣出次數_6M,0) AS FU_SEL_PROD_6M,
    round(賣出天數_6M,0) AS FU_SEL_DAY_6M,
    round(賣出口數_6M,0) AS FU_SEL_AMT_6M,
    round(交易次數_6ML,0) AS FU_TXN_PROD_6ML,
    round(交易天數_6ML,0) AS FU_TXN_DAY_6ML,
    round(交易口數_6ML,0) AS FU_TXN_AMT_6ML,
    round(買入次數_6ML,0) AS FU_BUY_PROD_6ML,
    round(買入天數_6ML,0) AS FU_BUY_DAY_6ML,
    round(買入口數_6ML,0) AS FU_BUY_AMT_6ML,
    round(賣出次數_6ML,0) AS FU_SEL_PROD_6ML,
    round(賣出天數_6ML,0) AS FU_SEL_DAY_6ML,
    round(賣出口數_6ML,0) AS FU_SEL_AMT_6ML,
    round(交易次數_12M,0) AS FU_TXN_PROD_12M,
    round(交易天數_12M,0) AS FU_TXN_DAY_12M,
    round(交易口數_12M,0) AS FU_TXN_AMT_12M,
    round(買入次數_12M,0) AS FU_BUY_PROD_12M,
    round(買入天數_12M,0) AS FU_BUY_DAY_12M,
    round(買入口數_12M,0) AS FU_BUY_AMT_12M,
    round(賣出次數_12M,0) AS FU_SEL_PROD_12M,
    round(賣出天數_12M,0) AS FU_SEL_DAY_12M,
    round(賣出口數_12M,0) AS FU_SEL_AMT_12M,
    round(交易次數_12ML,0) AS FU_TXN_PROD_12ML,
    round(交易天數_12ML,0) AS FU_TXN_DAY_12ML,
    round(交易口數_12ML,0) AS FU_TXN_AMT_12ML,
    round(買入次數_12ML,0) AS FU_BUY_PROD_12ML,
    round(買入天數_12ML,0) AS FU_BUY_DAY_12ML,
    round(買入口數_12ML,0) AS FU_BUY_AMT_12ML,
    round(賣出次數_12ML,0) AS FU_SEL_PROD_12ML,
    round(賣出天數_12ML,0) AS FU_SEL_DAY_12ML,
    round(賣出口數_12ML,0) AS FU_SEL_AMT_12ML,

    round(NVL(交易次數_M, 0) - NVL(交易次數_ML, 0),0) AS FU_TXN_PROD_M_MDIFF,
    round(NVL(交易天數_M, 0) - NVL(交易天數_ML, 0),0) AS FU_TXN_DAY_M_MDIFF,
    round(NVL(交易口數_M, 0) - NVL(交易口數_ML, 0),0) AS FU_TXN_AMT_M_MDIFF,
    round(NVL(買入次數_M, 0) - NVL(買入次數_ML, 0),0) AS FU_BUY_PROD_M_MDIFF,
    round(NVL(買入天數_M, 0) - NVL(買入天數_ML, 0),0) AS FU_BUY_DAY_M_MDIFF,
    round(NVL(買入口數_M, 0) - NVL(買入口數_ML, 0),0) AS FU_BUY_AMT_M_MDIFF,
    round(NVL(賣出次數_M, 0) - NVL(賣出次數_ML, 0),0) AS FU_SEL_PROD_M_MDIFF,
    round(NVL(賣出天數_M, 0) - NVL(賣出天數_ML, 0),0) AS FU_SEL_DAY_M_MDIFF,
    round(NVL(賣出口數_M, 0) - NVL(賣出口數_ML, 0),0) AS FU_SEL_AMT_M_MDIFF,
    
    round(CASE WHEN NVL(交易次數_ML, 0) <> 0  THEN (NVL(交易次數_M, 0) / NVL(交易次數_ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_PROD_M_RDIFF,
    round(CASE WHEN NVL(交易天數_ML, 0) <> 0  THEN (NVL(交易天數_M, 0) / NVL(交易天數_ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_DAY_M_RDIFF,
    round(CASE WHEN NVL(交易口數_ML, 0) <> 0  THEN (NVL(交易口數_M, 0) / NVL(交易口數_ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_AMT_M_RDIFF,
    round(CASE WHEN NVL(買入次數_ML, 0) <> 0  THEN (NVL(買入次數_M, 0) / NVL(買入次數_ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_PROD_M_RDIFF,
    round(CASE WHEN NVL(買入天數_ML, 0) <> 0  THEN (NVL(買入天數_M, 0) / NVL(買入天數_ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_DAY_M_RDIFF,
    round(CASE WHEN NVL(買入口數_ML, 0) <> 0  THEN (NVL(買入口數_M, 0) / NVL(買入口數_ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_AMT_M_RDIFF,
    round(CASE WHEN NVL(賣出次數_ML, 0) <> 0  THEN (NVL(賣出次數_M, 0) / NVL(賣出次數_ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_PROD_M_RDIFF,
    round(CASE WHEN NVL(賣出天數_ML, 0) <> 0  THEN (NVL(賣出天數_M, 0) / NVL(賣出天數_ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_DAY_M_RDIFF,
    round(CASE WHEN NVL(賣出口數_ML, 0) <> 0  THEN (NVL(賣出口數_M, 0) / NVL(賣出口數_ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_AMT_M_RDIFF,
    
    round(NVL(交易次數_3M, 0) - NVL(交易次數_3ML, 0),0) AS FU_TXN_PROD_3M_MDIFF,
    round(NVL(交易天數_3M, 0) - NVL(交易天數_3ML, 0),0) AS FU_TXN_DAY_3M_MDIFF,
    round(NVL(交易口數_3M, 0) - NVL(交易口數_3ML, 0),0) AS FU_TXN_AMT_3M_MDIFF,
    round(NVL(買入次數_3M, 0) - NVL(買入次數_3ML, 0),0) AS FU_BUY_PROD_3M_MDIFF,
    round(NVL(買入天數_3M, 0) - NVL(買入天數_3ML, 0),0) AS FU_BUY_DAY_3M_MDIFF,
    round(NVL(買入口數_3M, 0) - NVL(買入口數_3ML, 0),0) AS FU_BUY_AMT_3M_MDIFF,
    round(NVL(賣出次數_3M, 0) - NVL(賣出次數_3ML, 0),0) AS FU_SEL_PROD_3M_MDIFF,
    round(NVL(賣出天數_3M, 0) - NVL(賣出天數_3ML, 0),0) AS FU_SEL_DAY_3M_MDIFF,
    round(NVL(賣出口數_3M, 0) - NVL(賣出口數_3ML, 0),0) AS FU_SEL_AMT_3M_MDIFF,
    
    round(CASE WHEN NVL(交易次數_3ML, 0) <> 0  THEN (NVL(交易次數_3M, 0) / NVL(交易次數_3ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_PROD_3M_RDIFF,
    round(CASE WHEN NVL(交易天數_3ML, 0) <> 0  THEN (NVL(交易天數_3M, 0) / NVL(交易天數_3ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_DAY_3M_RDIFF,
    round(CASE WHEN NVL(交易口數_3ML, 0) <> 0  THEN (NVL(交易口數_3M, 0) / NVL(交易口數_3ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_AMT_3M_RDIFF,
    round(CASE WHEN NVL(買入次數_3ML, 0) <> 0  THEN (NVL(買入次數_3M, 0) / NVL(買入次數_3ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_PROD_3M_RDIFF,
    round(CASE WHEN NVL(買入天數_3ML, 0) <> 0  THEN (NVL(買入天數_3M, 0) / NVL(買入天數_3ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_DAY_3M_RDIFF,
    round(CASE WHEN NVL(買入口數_3ML, 0) <> 0  THEN (NVL(買入口數_3M, 0) / NVL(買入口數_3ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_AMT_3M_RDIFF,
    round(CASE WHEN NVL(賣出次數_3ML, 0) <> 0  THEN (NVL(賣出次數_3M, 0) / NVL(賣出次數_3ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_PROD_3M_RDIFF,
    round(CASE WHEN NVL(賣出天數_3ML, 0) <> 0  THEN (NVL(賣出天數_3M, 0) / NVL(賣出天數_3ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_DAY_3M_RDIFF,
    round(CASE WHEN NVL(賣出口數_3ML, 0) <> 0  THEN (NVL(賣出口數_3M, 0) / NVL(賣出口數_3ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_AMT_3M_RDIFF,
    
    round(NVL(交易次數_6M, 0) - NVL(交易次數_6ML, 0),0) AS FU_TXN_PROD_6M_MDIFF,
    round(NVL(交易天數_6M, 0) - NVL(交易天數_6ML, 0),0) AS FU_TXN_DAY_6M_MDIFF,
    round(NVL(交易口數_6M, 0) - NVL(交易口數_6ML, 0),0) AS FU_TXN_AMT_6M_MDIFF,
    round(NVL(買入次數_6M, 0) - NVL(買入次數_6ML, 0),0) AS FU_BUY_PROD_6M_MDIFF,
    round(NVL(買入天數_6M, 0) - NVL(買入天數_6ML, 0),0) AS FU_BUY_DAY_6M_MDIFF,
    round(NVL(買入口數_6M, 0) - NVL(買入口數_6ML, 0),0) AS FU_BUY_AMT_6M_MDIFF,
    round(NVL(賣出次數_6M, 0) - NVL(賣出次數_6ML, 0),0) AS FU_SEL_PROD_6M_MDIFF,
    round(NVL(賣出天數_6M, 0) - NVL(賣出天數_6ML, 0),0) AS FU_SEL_DAY_6M_MDIFF,
    round(NVL(賣出口數_6M, 0) - NVL(賣出口數_6ML, 0),0) AS FU_SEL_AMT_6M_MDIFF,
    
    round(CASE WHEN NVL(交易次數_6ML, 0) <> 0  THEN (NVL(交易次數_6M, 0) / NVL(交易次數_6ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_PROD_6M_RDIFF,
    round(CASE WHEN NVL(交易天數_6ML, 0) <> 0  THEN (NVL(交易天數_6M, 0) / NVL(交易天數_6ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_DAY_6M_RDIFF,
    round(CASE WHEN NVL(交易口數_6ML, 0) <> 0  THEN (NVL(交易口數_6M, 0) / NVL(交易口數_6ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_AMT_6M_RDIFF,
    round(CASE WHEN NVL(買入次數_6ML, 0) <> 0  THEN (NVL(買入次數_6M, 0) / NVL(買入次數_6ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_PROD_6M_RDIFF,
    round(CASE WHEN NVL(買入天數_6ML, 0) <> 0  THEN (NVL(買入天數_6M, 0) / NVL(買入天數_6ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_DAY_6M_RDIFF,
    round(CASE WHEN NVL(買入口數_6ML, 0) <> 0  THEN (NVL(買入口數_6M, 0) / NVL(買入口數_6ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_AMT_6M_RDIFF,
    round(CASE WHEN NVL(賣出次數_6ML, 0) <> 0  THEN (NVL(賣出次數_6M, 0) / NVL(賣出次數_6ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_PROD_6M_RDIFF,
    round(CASE WHEN NVL(賣出天數_6ML, 0) <> 0  THEN (NVL(賣出天數_6M, 0) / NVL(賣出天數_6ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_DAY_6M_RDIFF,
    round(CASE WHEN NVL(賣出口數_6ML, 0) <> 0  THEN (NVL(賣出口數_6M, 0) / NVL(賣出口數_6ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_AMT_6M_RDIFF,
    
    round(NVL(交易次數_12M, 0) - NVL(交易次數_12ML, 0),0) AS FU_TXN_PROD_12M_MDIFF,
    round(NVL(交易天數_12M, 0) - NVL(交易天數_12ML, 0),0) AS FU_TXN_DAY_12M_MDIFF,
    round(NVL(交易口數_12M, 0) - NVL(交易口數_12ML, 0),0) AS FU_TXN_AMT_12M_MDIFF,
    round(NVL(買入次數_12M, 0) - NVL(買入次數_12ML, 0),0) AS FU_BUY_PROD_12M_MDIFF,
    round(NVL(買入天數_12M, 0) - NVL(買入天數_12ML, 0),0) AS FU_BUY_DAY_12M_MDIFF,
    round(NVL(買入口數_12M, 0) - NVL(買入口數_12ML, 0),0) AS FU_BUY_AMT_12M_MDIFF,
    round(NVL(賣出次數_12M, 0) - NVL(賣出次數_12ML, 0),0) AS FU_SEL_PROD_12M_MDIFF,
    round(NVL(賣出天數_12M, 0) - NVL(賣出天數_12ML, 0),0) AS FU_SEL_DAY_12M_MDIFF,
    round(NVL(賣出口數_12M, 0) - NVL(賣出口數_12ML, 0),0) AS FU_SEL_AMT_12M_MDIFF,
    
    round(CASE WHEN NVL(交易次數_12ML, 0) <> 0  THEN (NVL(交易次數_12M, 0) / NVL(交易次數_12ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_PROD_12M_RDIFF,
    round(CASE WHEN NVL(交易天數_12ML, 0) <> 0  THEN (NVL(交易天數_12M, 0) / NVL(交易天數_12ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_DAY_12M_RDIFF,
    round(CASE WHEN NVL(交易口數_12ML, 0) <> 0  THEN (NVL(交易口數_12M, 0) / NVL(交易口數_12ML, 0) - 1) ELSE 0 END,4) AS FU_TXN_AMT_12M_RDIFF,
    round(CASE WHEN NVL(買入次數_12ML, 0) <> 0  THEN (NVL(買入次數_12M, 0) / NVL(買入次數_12ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_PROD_12M_RDIFF,
    round(CASE WHEN NVL(買入天數_12ML, 0) <> 0  THEN (NVL(買入天數_12M, 0) / NVL(買入天數_12ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_DAY_12M_RDIFF,
    round(CASE WHEN NVL(買入口數_12ML, 0) <> 0  THEN (NVL(買入口數_12M, 0) / NVL(買入口數_12ML, 0) - 1) ELSE 0 END,4) AS FU_BUY_AMT_12M_RDIFF,
    round(CASE WHEN NVL(賣出次數_12ML, 0) <> 0  THEN (NVL(賣出次數_12M, 0) / NVL(賣出次數_12ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_PROD_12M_RDIFF,
    round(CASE WHEN NVL(賣出天數_12ML, 0) <> 0  THEN (NVL(賣出天數_12M, 0) / NVL(賣出天數_12ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_DAY_12M_RDIFF,
    round(CASE WHEN NVL(賣出口數_12ML, 0) <> 0  THEN (NVL(賣出口數_12M, 0) / NVL(賣出口數_12ML, 0) - 1) ELSE 0 END,4) AS FU_SEL_AMT_12M_RDIFF

FROM TEMPFU2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_壽險---------------------------------------------------
INSERT INTO DS_SEC.CF_TXN_INSURANCE
WITH TEMPINSURANCE1
AS (
SELECT PARTY_ID_MASK CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(POLICY_AMT_TWD)AS 交易金額
FROM DM_S_VIEW.M_AT_INSURANCE_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym AND POLICY_STATUS_CODE NOT IN ('2','4')
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), 

TEMPINSURANCE2 AS (
SELECT  CUSTOMER_ID,
        :ym AS YYYYMM,

        SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END) AS 交易次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END) AS 交易天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END) AS 交易金額_M,

        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易金額_ML,

        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_3M,

        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_3ML,

        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_6M,

        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_6ML,

        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_12M,

        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_12ML

FROM TEMPINSURANCE1
GROUP BY CUSTOMER_ID
)

SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    INSURANCE_TXN_PROD_M,
    INSURANCE_TXN_DAY_M,
    INSURANCE_TXN_AMT_M,
    INSURANCE_TXN_PROD_3M,
    INSURANCE_TXN_DAY_3M,
    INSURANCE_TXN_AMT_3M,
    INSURANCE_TXN_PROD_6M,
    INSURANCE_TXN_DAY_6M,
    INSURANCE_TXN_AMT_6M,
    INSURANCE_TXN_PROD_12M,
    INSURANCE_TXN_DAY_12M,
    INSURANCE_TXN_AMT_12M,
    INSURANCE_TXN_PROD_M_MDIFF,
    INSURANCE_TXN_DAY_M_MDIFF,
    INSURANCE_TXN_AMT_M_MDIFF,
    INSURANCE_TXN_PROD_M_RDIFF,
    INSURANCE_TXN_DAY_M_RDIFF,
    INSURANCE_TXN_AMT_M_RDIFF,
    INSURANCE_TXN_PROD_3M_MDIFF,
    INSURANCE_TXN_DAY_3M_MDIFF,
    INSURANCE_TXN_AMT_3M_MDIFF,
    INSURANCE_TXN_PROD_3M_RDIFF,
    INSURANCE_TXN_DAY_3M_RDIFF,
    INSURANCE_TXN_AMT_3M_RDIFF,
    INSURANCE_TXN_PROD_6M_MDIFF,
    INSURANCE_TXN_DAY_6M_MDIFF,
    INSURANCE_TXN_AMT_6M_MDIFF,
    INSURANCE_TXN_PROD_6M_RDIFF,
    INSURANCE_TXN_DAY_6M_RDIFF,
    INSURANCE_TXN_AMT_6M_RDIFF,
    INSURANCE_TXN_PROD_12M_MDIFF,
    INSURANCE_TXN_DAY_12M_MDIFF,
    INSURANCE_TXN_AMT_12M_MDIFF,
    INSURANCE_TXN_PROD_12M_RDIFF,
    INSURANCE_TXN_DAY_12M_RDIFF,
    INSURANCE_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID,
        YYYYMM,
        round(交易次數_M,0) AS INSURANCE_TXN_PROD_M,
        round(交易天數_M,0) AS INSURANCE_TXN_DAY_M,
        round(交易金額_M,0) AS INSURANCE_TXN_AMT_M,
        
        round(交易次數_ML,0) AS INSURANCE_TXN_PROD_ML,
        round(交易天數_ML,0) AS INSURANCE_TXN_DAY_ML,
        round(交易金額_ML,0) AS INSURANCE_TXN_AMT_ML,
        
        round(交易次數_3M,0) AS INSURANCE_TXN_PROD_3M,
        round(交易天數_3M,0) AS INSURANCE_TXN_DAY_3M,
        round(交易金額_3M,0) AS INSURANCE_TXN_AMT_3M,
        
        round(交易次數_3ML,0) AS INSURANCE_TXN_PROD_3ML,
        round(交易天數_3ML,0) AS INSURANCE_TXN_DAY_3ML,
        round(交易金額_3ML,0) AS INSURANCE_TXN_AMT_3ML,
        
        round(交易次數_6M,0) AS INSURANCE_TXN_PROD_6M,
        round(交易天數_6M,0) AS INSURANCE_TXN_DAY_6M,
        round(交易金額_6M,0) AS INSURANCE_TXN_AMT_6M,
        
        round(交易次數_6ML,0) AS INSURANCE_TXN_PROD_6ML,
        round(交易天數_6ML,0) AS INSURANCE_TXN_DAY_6ML,
        round(交易金額_6ML,0) AS INSURANCE_TXN_AMT_6ML,
        
        round(交易次數_12M,0) AS INSURANCE_TXN_PROD_12M,
        round(交易天數_12M,0) AS INSURANCE_TXN_DAY_12M,
        round(交易金額_12M,0) AS INSURANCE_TXN_AMT_12M,
        
        round(交易次數_12ML,0) AS INSURANCE_TXN_PROD_12ML,
        round(交易天數_12ML,0) AS INSURANCE_TXN_DAY_12ML,
        round(交易金額_12ML,0) AS INSURANCE_TXN_AMT_12ML,

        round(NVL(交易次數_M, 0) - NVL(交易次數_ML, 0),0) AS INSURANCE_TXN_PROD_M_MDIFF,
        round(NVL(交易天數_M, 0) - NVL(交易天數_ML, 0),0) AS INSURANCE_TXN_DAY_M_MDIFF,
        round(NVL(交易金額_M, 0) - NVL(交易金額_ML, 0),0) AS INSURANCE_TXN_AMT_M_MDIFF,

        round(CASE WHEN NVL(交易次數_ML, 0) <> 0  THEN (NVL(交易次數_M, 0) / NVL(交易次數_ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_PROD_M_RDIFF,
        round(CASE WHEN NVL(交易天數_ML, 0) <> 0  THEN (NVL(交易天數_M, 0) / NVL(交易天數_ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_DAY_M_RDIFF,
        round(CASE WHEN NVL(交易金額_ML, 0) <> 0  THEN (NVL(交易金額_M, 0) / NVL(交易金額_ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_AMT_M_RDIFF,

        round(NVL(交易次數_3M, 0) - NVL(交易次數_3ML, 0),0) AS INSURANCE_TXN_PROD_3M_MDIFF,
        round(NVL(交易天數_3M, 0) - NVL(交易天數_3ML, 0),0) AS INSURANCE_TXN_DAY_3M_MDIFF,
        round(NVL(交易金額_3M, 0) - NVL(交易金額_3ML, 0),0) AS INSURANCE_TXN_AMT_3M_MDIFF,

        round(CASE WHEN NVL(交易次數_3ML, 0) <> 0  THEN (NVL(交易次數_3M, 0) / NVL(交易次數_3ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_PROD_3M_RDIFF,
        round(CASE WHEN NVL(交易天數_3ML, 0) <> 0  THEN (NVL(交易天數_3M, 0) / NVL(交易天數_3ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_DAY_3M_RDIFF,
        round(CASE WHEN NVL(交易金額_3ML, 0) <> 0  THEN (NVL(交易金額_3M, 0) / NVL(交易金額_3ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_AMT_3M_RDIFF,

        round(NVL(交易次數_6M, 0) - NVL(交易次數_6ML, 0),0) AS INSURANCE_TXN_PROD_6M_MDIFF,
        round(NVL(交易天數_6M, 0) - NVL(交易天數_6ML, 0),0) AS INSURANCE_TXN_DAY_6M_MDIFF,
        round(NVL(交易金額_6M, 0) - NVL(交易金額_6ML, 0),0) AS INSURANCE_TXN_AMT_6M_MDIFF,

        round(CASE WHEN NVL(交易次數_6ML, 0) <> 0  THEN (NVL(交易次數_6M, 0) / NVL(交易次數_6ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_PROD_6M_RDIFF,
        round(CASE WHEN NVL(交易天數_6ML, 0) <> 0  THEN (NVL(交易天數_6M, 0) / NVL(交易天數_6ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_DAY_6M_RDIFF,
        round(CASE WHEN NVL(交易金額_6ML, 0) <> 0  THEN (NVL(交易金額_6M, 0) / NVL(交易金額_6ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_AMT_6M_RDIFF,

        round(NVL(交易次數_12M, 0) - NVL(交易次數_12ML, 0),0) AS INSURANCE_TXN_PROD_12M_MDIFF,
        round(NVL(交易天數_12M, 0) - NVL(交易天數_12ML, 0),0) AS INSURANCE_TXN_DAY_12M_MDIFF,
        round(NVL(交易金額_12M, 0) - NVL(交易金額_12ML, 0),0) AS INSURANCE_TXN_AMT_12M_MDIFF,

        round(CASE WHEN NVL(交易次數_12ML, 0) <> 0  THEN (NVL(交易次數_12M, 0) / NVL(交易次數_12ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_PROD_12M_RDIFF,
        round(CASE WHEN NVL(交易天數_12ML, 0) <> 0  THEN (NVL(交易天數_12M, 0) / NVL(交易天數_12ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_DAY_12M_RDIFF,
        round(CASE WHEN NVL(交易金額_12ML, 0) <> 0  THEN (NVL(交易金額_12M, 0) / NVL(交易金額_12ML, 0) - 1) ELSE 0 END,4) AS INSURANCE_TXN_AMT_12M_RDIFF

FROM TEMPINSURANCE2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_結構型商品----------------------------------------------
INSERT INTO DS_SEC.CF_TXN_SN
WITH TEMPSN1
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '001' THEN TXN_DATE ELSE NULL END) AS 買入天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN 1 ELSE 0 END) AS 買入次數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END) AS 買入金額
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '002' THEN TXN_DATE ELSE NULL END) AS 賣出天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN 1 ELSE 0 END) AS 賣出次數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END) AS 賣出金額
FROM DM_S_VIEW.M_AT_SN_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
),

TEMPSN2
AS (
SELECT :ym AS YYYYMM,
        CUSTOMER_ID,
        
        SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END) AS 交易次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END) AS 交易天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END) AS 交易金額_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 買入次數 ELSE 0 END) AS 買入次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 買入天數 ELSE 0 END) AS 買入天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 買入金額 ELSE 0 END) AS 買入金額_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_M,
        
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易金額_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_ML,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END) AS 買入金額_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_3M,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_3ML,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END) AS 買入金額_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_6M,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_6ML,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END) AS 買入金額_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_12M,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_12ML

FROM TEMPSN1
GROUP BY CUSTOMER_ID
)

SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    SN_TXN_PROD_M,
    SN_TXN_DAY_M,
    SN_TXN_AMT_M,
    SN_BUY_PROD_M,
    SN_BUY_DAY_M,
    SN_BUY_AMT_M,
    SN_SEL_PROD_M,
    SN_SEL_DAY_M,
    SN_SEL_AMT_M,
    SN_TXN_PROD_3M,
    SN_TXN_DAY_3M,
    SN_TXN_AMT_3M,
    SN_BUY_PROD_3M,
    SN_BUY_DAY_3M,
    SN_BUY_AMT_3M,
    SN_SEL_PROD_3M,
    SN_SEL_DAY_3M,
    SN_SEL_AMT_3M,
    SN_TXN_PROD_6M,
    SN_TXN_DAY_6M,
    SN_TXN_AMT_6M,
    SN_BUY_PROD_6M,
    SN_BUY_DAY_6M,
    SN_BUY_AMT_6M,
    SN_SEL_PROD_6M,
    SN_SEL_DAY_6M,
    SN_SEL_AMT_6M,
    SN_TXN_PROD_12M,
    SN_TXN_DAY_12M,
    SN_TXN_AMT_12M,
    SN_BUY_PROD_12M,
    SN_BUY_DAY_12M,
    SN_BUY_AMT_12M,
    SN_SEL_PROD_12M,
    SN_SEL_DAY_12M,
    SN_SEL_AMT_12M,
    SN_TXN_PROD_M_MDIFF,
    SN_TXN_DAY_M_MDIFF,
    SN_TXN_AMT_M_MDIFF,
    SN_BUY_PROD_M_MDIFF,
    SN_BUY_DAY_M_MDIFF,
    SN_BUY_AMT_M_MDIFF,
    SN_SEL_PROD_M_MDIFF,
    SN_SEL_DAY_M_MDIFF,
    SN_SEL_AMT_M_MDIFF,
    SN_TXN_PROD_M_RDIFF,
    SN_TXN_DAY_M_RDIFF,
    SN_TXN_AMT_M_RDIFF,
    SN_BUY_PROD_M_RDIFF,
    SN_BUY_DAY_M_RDIFF,
    SN_BUY_AMT_M_RDIFF,
    SN_SEL_PROD_M_RDIFF,
    SN_SEL_DAY_M_RDIFF,
    SN_SEL_AMT_M_RDIFF,
    SN_TXN_PROD_3M_MDIFF,
    SN_TXN_DAY_3M_MDIFF,
    SN_TXN_AMT_3M_MDIFF,
    SN_BUY_PROD_3M_MDIFF,
    SN_BUY_DAY_3M_MDIFF,
    SN_BUY_AMT_3M_MDIFF,
    SN_SEL_PROD_3M_MDIFF,
    SN_SEL_DAY_3M_MDIFF,
    SN_SEL_AMT_3M_MDIFF,
    SN_TXN_PROD_3M_RDIFF,
    SN_TXN_DAY_3M_RDIFF,
    SN_TXN_AMT_3M_RDIFF,
    SN_BUY_PROD_3M_RDIFF,
    SN_BUY_DAY_3M_RDIFF,
    SN_BUY_AMT_3M_RDIFF,
    SN_SEL_PROD_3M_RDIFF,
    SN_SEL_DAY_3M_RDIFF,
    SN_SEL_AMT_3M_RDIFF,
    SN_TXN_PROD_6M_MDIFF,
    SN_TXN_DAY_6M_MDIFF,
    SN_TXN_AMT_6M_MDIFF,
    SN_BUY_PROD_6M_MDIFF,
    SN_BUY_DAY_6M_MDIFF,
    SN_BUY_AMT_6M_MDIFF,
    SN_SEL_PROD_6M_MDIFF,
    SN_SEL_DAY_6M_MDIFF,
    SN_SEL_AMT_6M_MDIFF,
    SN_TXN_PROD_6M_RDIFF,
    SN_TXN_DAY_6M_RDIFF,
    SN_TXN_AMT_6M_RDIFF,
    SN_BUY_PROD_6M_RDIFF,
    SN_BUY_DAY_6M_RDIFF,
    SN_BUY_AMT_6M_RDIFF,
    SN_SEL_PROD_6M_RDIFF,
    SN_SEL_DAY_6M_RDIFF,
    SN_SEL_AMT_6M_RDIFF,
    SN_TXN_PROD_12M_MDIFF,
    SN_TXN_DAY_12M_MDIFF,
    SN_TXN_AMT_12M_MDIFF,
    SN_BUY_PROD_12M_MDIFF,
    SN_BUY_DAY_12M_MDIFF,
    SN_BUY_AMT_12M_MDIFF,
    SN_SEL_PROD_12M_MDIFF,
    SN_SEL_DAY_12M_MDIFF,
    SN_SEL_AMT_12M_MDIFF,
    SN_TXN_PROD_12M_RDIFF,
    SN_TXN_DAY_12M_RDIFF,
    SN_TXN_AMT_12M_RDIFF,
    SN_BUY_PROD_12M_RDIFF,
    SN_BUY_DAY_12M_RDIFF,
    SN_BUY_AMT_12M_RDIFF,
    SN_SEL_PROD_12M_RDIFF,
    SN_SEL_DAY_12M_RDIFF,
    SN_SEL_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
SELECT CUSTOMER_ID,
        YYYYMM,
        ROUND(交易次數_M,0) AS SN_TXN_PROD_M,
        ROUND(交易天數_M,0) AS SN_TXN_DAY_M,
        ROUND(交易金額_M,0) AS SN_TXN_AMT_M,
        ROUND(買入次數_M,0) AS SN_BUY_PROD_M,
        ROUND(買入天數_M,0) AS SN_BUY_DAY_M,
        ROUND(買入金額_M,0) AS SN_BUY_AMT_M,
        ROUND(賣出次數_M,0) AS SN_SEL_PROD_M,
        ROUND(賣出天數_M,0) AS SN_SEL_DAY_M,
        ROUND(賣出金額_M,0) AS SN_SEL_AMT_M,
        ROUND(交易次數_ML,0) AS SN_TXN_PROD_ML,
        ROUND(交易天數_ML,0) AS SN_TXN_DAY_ML,
        ROUND(交易金額_ML,0) AS SN_TXN_AMT_ML,
        ROUND(買入次數_ML,0) AS SN_BUY_PROD_ML,
        ROUND(買入天數_ML,0) AS SN_BUY_DAY_ML,
        ROUND(買入金額_ML,0) AS SN_BUY_AMT_ML,
        ROUND(賣出次數_ML,0) AS SN_SEL_PROD_ML,
        ROUND(賣出天數_ML,0) AS SN_SEL_DAY_ML,
        ROUND(賣出金額_ML,0) AS SN_SEL_AMT_ML,
        ROUND(交易次數_3M,0) AS SN_TXN_PROD_3M,
        ROUND(交易天數_3M,0) AS SN_TXN_DAY_3M,
        ROUND(交易金額_3M,0) AS SN_TXN_AMT_3M,
        ROUND(買入次數_3M,0) AS SN_BUY_PROD_3M,
        ROUND(買入天數_3M,0) AS SN_BUY_DAY_3M,
        ROUND(買入金額_3M,0) AS SN_BUY_AMT_3M,
        ROUND(賣出次數_3M,0) AS SN_SEL_PROD_3M,
        ROUND(賣出天數_3M,0) AS SN_SEL_DAY_3M,
        ROUND(賣出金額_3M,0) AS SN_SEL_AMT_3M,
        ROUND(交易次數_3ML,0) AS SN_TXN_PROD_3ML,
        ROUND(交易天數_3ML,0) AS SN_TXN_DAY_3ML,
        ROUND(交易金額_3ML,0) AS SN_TXN_AMT_3ML,
        ROUND(買入次數_3ML,0) AS SN_BUY_PROD_3ML,
        ROUND(買入天數_3ML,0) AS SN_BUY_DAY_3ML,
        ROUND(買入金額_3ML,0) AS SN_BUY_AMT_3ML,
        ROUND(賣出次數_3ML,0) AS SN_SEL_PROD_3ML,
        ROUND(賣出天數_3ML,0) AS SN_SEL_DAY_3ML,
        ROUND(賣出金額_3ML,0) AS SN_SEL_AMT_3ML,
        ROUND(交易次數_6M,0) AS SN_TXN_PROD_6M,
        ROUND(交易天數_6M,0) AS SN_TXN_DAY_6M,
        ROUND(交易金額_6M,0) AS SN_TXN_AMT_6M,
        ROUND(買入次數_6M,0) AS SN_BUY_PROD_6M,
        ROUND(買入天數_6M,0) AS SN_BUY_DAY_6M,
        ROUND(買入金額_6M,0) AS SN_BUY_AMT_6M,
        ROUND(賣出次數_6M,0) AS SN_SEL_PROD_6M,
        ROUND(賣出天數_6M,0) AS SN_SEL_DAY_6M,
        ROUND(賣出金額_6M,0) AS SN_SEL_AMT_6M,
        ROUND(交易次數_6ML,0) AS SN_TXN_PROD_6ML,
        ROUND(交易天數_6ML,0) AS SN_TXN_DAY_6ML,
        ROUND(交易金額_6ML,0) AS SN_TXN_AMT_6ML,
        ROUND(買入次數_6ML,0) AS SN_BUY_PROD_6ML,
        ROUND(買入天數_6ML,0) AS SN_BUY_DAY_6ML,
        ROUND(買入金額_6ML,0) AS SN_BUY_AMT_6ML,
        ROUND(賣出次數_6ML,0) AS SN_SEL_PROD_6ML,
        ROUND(賣出天數_6ML,0) AS SN_SEL_DAY_6ML,
        ROUND(賣出金額_6ML,0) AS SN_SEL_AMT_6ML,
        ROUND(交易次數_12M,0) AS SN_TXN_PROD_12M,
        ROUND(交易天數_12M,0) AS SN_TXN_DAY_12M,
        ROUND(交易金額_12M,0) AS SN_TXN_AMT_12M,
        ROUND(買入次數_12M,0) AS SN_BUY_PROD_12M,
        ROUND(買入天數_12M,0) AS SN_BUY_DAY_12M,
        ROUND(買入金額_12M,0) AS SN_BUY_AMT_12M,
        ROUND(賣出次數_12M,0) AS SN_SEL_PROD_12M,
        ROUND(賣出天數_12M,0) AS SN_SEL_DAY_12M,
        ROUND(賣出金額_12M,0) AS SN_SEL_AMT_12M,
        ROUND(交易次數_12ML,0) AS SN_TXN_PROD_12ML,
        ROUND(交易天數_12ML,0) AS SN_TXN_DAY_12ML,
        ROUND(交易金額_12ML,0) AS SN_TXN_AMT_12ML,
        ROUND(買入次數_12ML,0) AS SN_BUY_PROD_12ML,
        ROUND(買入天數_12ML,0) AS SN_BUY_DAY_12ML,
        ROUND(買入金額_12ML,0) AS SN_BUY_AMT_12ML,
        ROUND(賣出次數_12ML,0) AS SN_SEL_PROD_12ML,
        ROUND(賣出天數_12ML,0) AS SN_SEL_DAY_12ML,
        ROUND(賣出金額_12ML,0) AS SN_SEL_AMT_12ML,

        ROUND(NVL(交易次數_M, 0) - NVL(交易次數_ML, 0),0) AS SN_TXN_PROD_M_MDIFF,
        ROUND(NVL(交易天數_M, 0) - NVL(交易天數_ML, 0),0) AS SN_TXN_DAY_M_MDIFF,
        ROUND(NVL(交易金額_M, 0) - NVL(交易金額_ML, 0),0) AS SN_TXN_AMT_M_MDIFF,
        ROUND(NVL(買入次數_M, 0) - NVL(買入次數_ML, 0),0) AS SN_BUY_PROD_M_MDIFF,
        ROUND(NVL(買入天數_M, 0) - NVL(買入天數_ML, 0),0) AS SN_BUY_DAY_M_MDIFF,
        ROUND(NVL(買入金額_M, 0) - NVL(買入金額_ML, 0),0) AS SN_BUY_AMT_M_MDIFF,
        ROUND(NVL(賣出次數_M, 0) - NVL(賣出次數_ML, 0),0) AS SN_SEL_PROD_M_MDIFF,
        ROUND(NVL(賣出天數_M, 0) - NVL(賣出天數_ML, 0),0) AS SN_SEL_DAY_M_MDIFF,
        ROUND(NVL(賣出金額_M, 0) - NVL(賣出金額_ML, 0),0) AS SN_SEL_AMT_M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_ML, 0) <> 0  THEN (NVL(交易次數_M, 0) / NVL(交易次數_ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_PROD_M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_ML, 0) <> 0  THEN (NVL(交易天數_M, 0) / NVL(交易天數_ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_DAY_M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_ML, 0) <> 0  THEN (NVL(交易金額_M, 0) / NVL(交易金額_ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_AMT_M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_ML, 0) <> 0  THEN (NVL(買入次數_M, 0) / NVL(買入次數_ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_PROD_M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_ML, 0) <> 0  THEN (NVL(買入天數_M, 0) / NVL(買入天數_ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_DAY_M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_ML, 0) <> 0  THEN (NVL(買入金額_M, 0) / NVL(買入金額_ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_AMT_M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_ML, 0) <> 0  THEN (NVL(賣出次數_M, 0) / NVL(賣出次數_ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_PROD_M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_ML, 0) <> 0  THEN (NVL(賣出天數_M, 0) / NVL(賣出天數_ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_DAY_M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_ML, 0) <> 0  THEN (NVL(賣出金額_M, 0) / NVL(賣出金額_ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_AMT_M_RDIFF,

        ROUND(NVL(交易次數_3M, 0) - NVL(交易次數_3ML, 0),0) AS SN_TXN_PROD_3M_MDIFF,
        ROUND(NVL(交易天數_3M, 0) - NVL(交易天數_3ML, 0),0) AS SN_TXN_DAY_3M_MDIFF,
        ROUND(NVL(交易金額_3M, 0) - NVL(交易金額_3ML, 0),0) AS SN_TXN_AMT_3M_MDIFF,
        ROUND(NVL(買入次數_3M, 0) - NVL(買入次數_3ML, 0),0) AS SN_BUY_PROD_3M_MDIFF,
        ROUND(NVL(買入天數_3M, 0) - NVL(買入天數_3ML, 0),0) AS SN_BUY_DAY_3M_MDIFF,
        ROUND(NVL(買入金額_3M, 0) - NVL(買入金額_3ML, 0),0) AS SN_BUY_AMT_3M_MDIFF,
        ROUND(NVL(賣出次數_3M, 0) - NVL(賣出次數_3ML, 0),0) AS SN_SEL_PROD_3M_MDIFF,
        ROUND(NVL(賣出天數_3M, 0) - NVL(賣出天數_3ML, 0),0) AS SN_SEL_DAY_3M_MDIFF,
        ROUND(NVL(賣出金額_3M, 0) - NVL(賣出金額_3ML, 0),0) AS SN_SEL_AMT_3M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_3ML, 0) <> 0  THEN (NVL(交易次數_3M, 0) / NVL(交易次數_3ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_PROD_3M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_3ML, 0) <> 0  THEN (NVL(交易天數_3M, 0) / NVL(交易天數_3ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_DAY_3M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_3ML, 0) <> 0  THEN (NVL(交易金額_3M, 0) / NVL(交易金額_3ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_AMT_3M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_3ML, 0) <> 0  THEN (NVL(買入次數_3M, 0) / NVL(買入次數_3ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_PROD_3M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_3ML, 0) <> 0  THEN (NVL(買入天數_3M, 0) / NVL(買入天數_3ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_DAY_3M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_3ML, 0) <> 0  THEN (NVL(買入金額_3M, 0) / NVL(買入金額_3ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_AMT_3M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_3ML, 0) <> 0  THEN (NVL(賣出次數_3M, 0) / NVL(賣出次數_3ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_PROD_3M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_3ML, 0) <> 0  THEN (NVL(賣出天數_3M, 0) / NVL(賣出天數_3ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_DAY_3M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_3ML, 0) <> 0  THEN (NVL(賣出金額_3M, 0) / NVL(賣出金額_3ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_AMT_3M_RDIFF,

        ROUND(NVL(交易次數_6M, 0) - NVL(交易次數_6ML, 0),0) AS SN_TXN_PROD_6M_MDIFF,
        ROUND(NVL(交易天數_6M, 0) - NVL(交易天數_6ML, 0),0) AS SN_TXN_DAY_6M_MDIFF,
        ROUND(NVL(交易金額_6M, 0) - NVL(交易金額_6ML, 0),0) AS SN_TXN_AMT_6M_MDIFF,
        ROUND(NVL(買入次數_6M, 0) - NVL(買入次數_6ML, 0),0) AS SN_BUY_PROD_6M_MDIFF,
        ROUND(NVL(買入天數_6M, 0) - NVL(買入天數_6ML, 0),0) AS SN_BUY_DAY_6M_MDIFF,
        ROUND(NVL(買入金額_6M, 0) - NVL(買入金額_6ML, 0),0) AS SN_BUY_AMT_6M_MDIFF,
        ROUND(NVL(賣出次數_6M, 0) - NVL(賣出次數_6ML, 0),0) AS SN_SEL_PROD_6M_MDIFF,
        ROUND(NVL(賣出天數_6M, 0) - NVL(賣出天數_6ML, 0),0) AS SN_SEL_DAY_6M_MDIFF,
        ROUND(NVL(賣出金額_6M, 0) - NVL(賣出金額_6ML, 0),0) AS SN_SEL_AMT_6M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_6ML, 0) <> 0  THEN (NVL(交易次數_6M, 0) / NVL(交易次數_6ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_PROD_6M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_6ML, 0) <> 0  THEN (NVL(交易天數_6M, 0) / NVL(交易天數_6ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_DAY_6M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_6ML, 0) <> 0  THEN (NVL(交易金額_6M, 0) / NVL(交易金額_6ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_AMT_6M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_6ML, 0) <> 0  THEN (NVL(買入次數_6M, 0) / NVL(買入次數_6ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_PROD_6M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_6ML, 0) <> 0  THEN (NVL(買入天數_6M, 0) / NVL(買入天數_6ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_DAY_6M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_6ML, 0) <> 0  THEN (NVL(買入金額_6M, 0) / NVL(買入金額_6ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_AMT_6M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_6ML, 0) <> 0  THEN (NVL(賣出次數_6M, 0) / NVL(賣出次數_6ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_PROD_6M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_6ML, 0) <> 0  THEN (NVL(賣出天數_6M, 0) / NVL(賣出天數_6ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_DAY_6M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_6ML, 0) <> 0  THEN (NVL(賣出金額_6M, 0) / NVL(賣出金額_6ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_AMT_6M_RDIFF,

        ROUND(NVL(交易次數_12M, 0) - NVL(交易次數_12ML, 0),0) AS SN_TXN_PROD_12M_MDIFF,
        ROUND(NVL(交易天數_12M, 0) - NVL(交易天數_12ML, 0),0) AS SN_TXN_DAY_12M_MDIFF,
        ROUND(NVL(交易金額_12M, 0) - NVL(交易金額_12ML, 0),0) AS SN_TXN_AMT_12M_MDIFF,
        ROUND(NVL(買入次數_12M, 0) - NVL(買入次數_12ML, 0),0) AS SN_BUY_PROD_12M_MDIFF,
        ROUND(NVL(買入天數_12M, 0) - NVL(買入天數_12ML, 0),0) AS SN_BUY_DAY_12M_MDIFF,
        ROUND(NVL(買入金額_12M, 0) - NVL(買入金額_12ML, 0),0) AS SN_BUY_AMT_12M_MDIFF,
        ROUND(NVL(賣出次數_12M, 0) - NVL(賣出次數_12ML, 0),0) AS SN_SEL_PROD_12M_MDIFF,
        ROUND(NVL(賣出天數_12M, 0) - NVL(賣出天數_12ML, 0),0) AS SN_SEL_DAY_12M_MDIFF,
        ROUND(NVL(賣出金額_12M, 0) - NVL(賣出金額_12ML, 0),0) AS SN_SEL_AMT_12M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_12ML, 0) <> 0  THEN (NVL(交易次數_12M, 0) / NVL(交易次數_12ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_PROD_12M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_12ML, 0) <> 0  THEN (NVL(交易天數_12M, 0) / NVL(交易天數_12ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_DAY_12M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_12ML, 0) <> 0  THEN (NVL(交易金額_12M, 0) / NVL(交易金額_12ML, 0) - 1) ELSE 0 END,4) AS SN_TXN_AMT_12M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_12ML, 0) <> 0  THEN (NVL(買入次數_12M, 0) / NVL(買入次數_12ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_PROD_12M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_12ML, 0) <> 0  THEN (NVL(買入天數_12M, 0) / NVL(買入天數_12ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_DAY_12M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_12ML, 0) <> 0  THEN (NVL(買入金額_12M, 0) / NVL(買入金額_12ML, 0) - 1) ELSE 0 END,4) AS SN_BUY_AMT_12M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_12ML, 0) <> 0  THEN (NVL(賣出次數_12M, 0) / NVL(賣出次數_12ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_PROD_12M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_12ML, 0) <> 0  THEN (NVL(賣出天數_12M, 0) / NVL(賣出天數_12ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_DAY_12M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_12ML, 0) <> 0  THEN (NVL(賣出金額_12M, 0) / NVL(賣出金額_12ML, 0) - 1) ELSE 0 END,4) AS SN_SEL_AMT_12M_RDIFF

FROM TEMPSN2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
----------------------------------交易_海外債-------------------------------------------------
INSERT INTO DS_SEC.CF_TXN_FB
WITH TEMPFB1 
AS (
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '001' THEN TXN_DATE ELSE NULL END) AS 買入天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN 1 ELSE 0 END) AS 買入次數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END) AS 買入金額
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '002' THEN TXN_DATE ELSE NULL END) AS 賣出天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN 1 ELSE 0 END) AS 賣出次數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END) AS 賣出金額
FROM DM_S_VIEW.M_AT_BOND_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), 
TEMPFB2 AS (
SELECT :ym AS YYYYMM,
CUSTOMER_ID,
        
        SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END) AS 交易次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END) AS 交易天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END) AS 交易金額_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 買入次數 ELSE 0 END) AS 買入次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 買入天數 ELSE 0 END) AS 買入天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 買入金額 ELSE 0 END) AS 買入金額_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_M,
        SUM(CASE WHEN YYYYMM = :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_M,
        
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易金額_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_ML,
        SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_ML,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END) AS 買入金額_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_3M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_3M,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_3ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_3ML,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END) AS 買入金額_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_6M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_6M,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_6ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_6ML,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END) AS 交易次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END) AS 交易天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END) AS 交易金額_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END) AS 買入次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END) AS 買入天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END) AS 買入金額_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END) AS 賣出次數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END) AS 賣出天數_12M,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END) AS 賣出金額_12M,
        
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END) AS 交易次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END) AS 交易天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END) AS 交易金額_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入次數 ELSE 0 END) AS 買入次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入天數 ELSE 0 END) AS 買入天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入金額 ELSE 0 END) AS 買入金額_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出次數 ELSE 0 END) AS 賣出次數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出天數 ELSE 0 END) AS 賣出天數_12ML,
        SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出金額 ELSE 0 END) AS 賣出金額_12ML

FROM TEMPFB1
GROUP BY CUSTOMER_ID
)
----第二階衍生資料計算
SELECT
    A.CUSTOMER_ID,
    A.YYYYMM,
    FB_TXN_PROD_M,
    FB_TXN_DAY_M,
    FB_TXN_AMT_M,
    FB_BUY_PROD_M,
    FB_BUY_DAY_M,
    FB_BUY_AMT_M,
    FB_SEL_PROD_M,
    FB_SEL_DAY_M,
    FB_SEL_AMT_M,
    FB_TXN_PROD_3M,
    FB_TXN_DAY_3M,
    FB_TXN_AMT_3M,
    FB_BUY_PROD_3M,
    FB_BUY_DAY_3M,
    FB_BUY_AMT_3M,
    FB_SEL_PROD_3M,
    FB_SEL_DAY_3M,
    FB_SEL_AMT_3M,
    FB_TXN_PROD_6M,
    FB_TXN_DAY_6M,
    FB_TXN_AMT_6M,
    FB_BUY_PROD_6M,
    FB_BUY_DAY_6M,
    FB_BUY_AMT_6M,
    FB_SEL_PROD_6M,
    FB_SEL_DAY_6M,
    FB_SEL_AMT_6M,
    FB_TXN_PROD_12M,
    FB_TXN_DAY_12M,
    FB_TXN_AMT_12M,
    FB_BUY_PROD_12M,
    FB_BUY_DAY_12M,
    FB_BUY_AMT_12M,
    FB_SEL_PROD_12M,
    FB_SEL_DAY_12M,
    FB_SEL_AMT_12M,
    FB_TXN_PROD_M_MDIFF,
    FB_TXN_DAY_M_MDIFF,
    FB_TXN_AMT_M_MDIFF,
    FB_BUY_PROD_M_MDIFF,
    FB_BUY_DAY_M_MDIFF,
    FB_BUY_AMT_M_MDIFF,
    FB_SEL_PROD_M_MDIFF,
    FB_SEL_DAY_M_MDIFF,
    FB_SEL_AMT_M_MDIFF,
    FB_TXN_PROD_M_RDIFF,
    FB_TXN_DAY_M_RDIFF,
    FB_TXN_AMT_M_RDIFF,
    FB_BUY_PROD_M_RDIFF,
    FB_BUY_DAY_M_RDIFF,
    FB_BUY_AMT_M_RDIFF,
    FB_SEL_PROD_M_RDIFF,
    FB_SEL_DAY_M_RDIFF,
    FB_SEL_AMT_M_RDIFF,
    FB_TXN_PROD_3M_MDIFF,
    FB_TXN_DAY_3M_MDIFF,
    FB_TXN_AMT_3M_MDIFF,
    FB_BUY_PROD_3M_MDIFF,
    FB_BUY_DAY_3M_MDIFF,
    FB_BUY_AMT_3M_MDIFF,
    FB_SEL_PROD_3M_MDIFF,
    FB_SEL_DAY_3M_MDIFF,
    FB_SEL_AMT_3M_MDIFF,
    FB_TXN_PROD_3M_RDIFF,
    FB_TXN_DAY_3M_RDIFF,
    FB_TXN_AMT_3M_RDIFF,
    FB_BUY_PROD_3M_RDIFF,
    FB_BUY_DAY_3M_RDIFF,
    FB_BUY_AMT_3M_RDIFF,
    FB_SEL_PROD_3M_RDIFF,
    FB_SEL_DAY_3M_RDIFF,
    FB_SEL_AMT_3M_RDIFF,
    FB_TXN_PROD_6M_MDIFF,
    FB_TXN_DAY_6M_MDIFF,
    FB_TXN_AMT_6M_MDIFF,
    FB_BUY_PROD_6M_MDIFF,
    FB_BUY_DAY_6M_MDIFF,
    FB_BUY_AMT_6M_MDIFF,
    FB_SEL_PROD_6M_MDIFF,
    FB_SEL_DAY_6M_MDIFF,
    FB_SEL_AMT_6M_MDIFF,
    FB_TXN_PROD_6M_RDIFF,
    FB_TXN_DAY_6M_RDIFF,
    FB_TXN_AMT_6M_RDIFF,
    FB_BUY_PROD_6M_RDIFF,
    FB_BUY_DAY_6M_RDIFF,
    FB_BUY_AMT_6M_RDIFF,
    FB_SEL_PROD_6M_RDIFF,
    FB_SEL_DAY_6M_RDIFF,
    FB_SEL_AMT_6M_RDIFF,
    FB_TXN_PROD_12M_MDIFF,
    FB_TXN_DAY_12M_MDIFF,
    FB_TXN_AMT_12M_MDIFF,
    FB_BUY_PROD_12M_MDIFF,
    FB_BUY_DAY_12M_MDIFF,
    FB_BUY_AMT_12M_MDIFF,
    FB_SEL_PROD_12M_MDIFF,
    FB_SEL_DAY_12M_MDIFF,
    FB_SEL_AMT_12M_MDIFF,
    FB_TXN_PROD_12M_RDIFF,
    FB_TXN_DAY_12M_RDIFF,
    FB_TXN_AMT_12M_RDIFF,
    FB_BUY_PROD_12M_RDIFF,
    FB_BUY_DAY_12M_RDIFF,
    FB_BUY_AMT_12M_RDIFF,
    FB_SEL_PROD_12M_RDIFF,
    FB_SEL_DAY_12M_RDIFF,
    FB_SEL_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID,
        YYYYMM,
        ROUND(交易次數_M,0) AS FB_TXN_PROD_M,
        ROUND(交易天數_M,0) AS FB_TXN_DAY_M,
        ROUND(交易金額_M,0) AS FB_TXN_AMT_M,
        ROUND(買入次數_M,0) AS FB_BUY_PROD_M,
        ROUND(買入天數_M,0) AS FB_BUY_DAY_M,
        ROUND(買入金額_M,0) AS FB_BUY_AMT_M,
        ROUND(賣出次數_M,0) AS FB_SEL_PROD_M,
        ROUND(賣出天數_M,0) AS FB_SEL_DAY_M,
        ROUND(賣出金額_M,0) AS FB_SEL_AMT_M,
        ROUND(交易次數_ML,0) AS FB_TXN_PROD_ML,
        ROUND(交易天數_ML,0) AS FB_TXN_DAY_ML,
        ROUND(交易金額_ML,0) AS FB_TXN_AMT_ML,
        ROUND(買入次數_ML,0) AS FB_BUY_PROD_ML,
        ROUND(買入天數_ML,0) AS FB_BUY_DAY_ML,
        ROUND(買入金額_ML,0) AS FB_BUY_AMT_ML,
        ROUND(賣出次數_ML,0) AS FB_SEL_PROD_ML,
        ROUND(賣出天數_ML,0) AS FB_SEL_DAY_ML,
        ROUND(賣出金額_ML,0) AS FB_SEL_AMT_ML,
        ROUND(交易次數_3M,0) AS FB_TXN_PROD_3M,
        ROUND(交易天數_3M,0) AS FB_TXN_DAY_3M,
        ROUND(交易金額_3M,0) AS FB_TXN_AMT_3M,
        ROUND(買入次數_3M,0) AS FB_BUY_PROD_3M,
        ROUND(買入天數_3M,0) AS FB_BUY_DAY_3M,
        ROUND(買入金額_3M,0) AS FB_BUY_AMT_3M,
        ROUND(賣出次數_3M,0) AS FB_SEL_PROD_3M,
        ROUND(賣出天數_3M,0) AS FB_SEL_DAY_3M,
        ROUND(賣出金額_3M,0) AS FB_SEL_AMT_3M,
        ROUND(交易次數_3ML,0) AS FB_TXN_PROD_3ML,
        ROUND(交易天數_3ML,0) AS FB_TXN_DAY_3ML,
        ROUND(交易金額_3ML,0) AS FB_TXN_AMT_3ML,
        ROUND(買入次數_3ML,0) AS FB_BUY_PROD_3ML,
        ROUND(買入天數_3ML,0) AS FB_BUY_DAY_3ML,
        ROUND(買入金額_3ML,0) AS FB_BUY_AMT_3ML,
        ROUND(賣出次數_3ML,0) AS FB_SEL_PROD_3ML,
        ROUND(賣出天數_3ML,0) AS FB_SEL_DAY_3ML,
        ROUND(賣出金額_3ML,0) AS FB_SEL_AMT_3ML,
        ROUND(交易次數_6M,0) AS FB_TXN_PROD_6M,
        ROUND(交易天數_6M,0) AS FB_TXN_DAY_6M,
        ROUND(交易金額_6M,0) AS FB_TXN_AMT_6M,
        ROUND(買入次數_6M,0) AS FB_BUY_PROD_6M,
        ROUND(買入天數_6M,0) AS FB_BUY_DAY_6M,
        ROUND(買入金額_6M,0) AS FB_BUY_AMT_6M,
        ROUND(賣出次數_6M,0) AS FB_SEL_PROD_6M,
        ROUND(賣出天數_6M,0) AS FB_SEL_DAY_6M,
        ROUND(賣出金額_6M,0) AS FB_SEL_AMT_6M,
        ROUND(交易次數_6ML,0) AS FB_TXN_PROD_6ML,
        ROUND(交易天數_6ML,0) AS FB_TXN_DAY_6ML,
        ROUND(交易金額_6ML,0) AS FB_TXN_AMT_6ML,
        ROUND(買入次數_6ML,0) AS FB_BUY_PROD_6ML,
        ROUND(買入天數_6ML,0) AS FB_BUY_DAY_6ML,
        ROUND(買入金額_6ML,0) AS FB_BUY_AMT_6ML,
        ROUND(賣出次數_6ML,0) AS FB_SEL_PROD_6ML,
        ROUND(賣出天數_6ML,0) AS FB_SEL_DAY_6ML,
        ROUND(賣出金額_6ML,0) AS FB_SEL_AMT_6ML,
        ROUND(交易次數_12M,0) AS FB_TXN_PROD_12M,
        ROUND(交易天數_12M,0) AS FB_TXN_DAY_12M,
        ROUND(交易金額_12M,0) AS FB_TXN_AMT_12M,
        ROUND(買入次數_12M,0) AS FB_BUY_PROD_12M,
        ROUND(買入天數_12M,0) AS FB_BUY_DAY_12M,
        ROUND(買入金額_12M,0) AS FB_BUY_AMT_12M,
        ROUND(賣出次數_12M,0) AS FB_SEL_PROD_12M,
        ROUND(賣出天數_12M,0) AS FB_SEL_DAY_12M,
        ROUND(賣出金額_12M,0) AS FB_SEL_AMT_12M,
        ROUND(交易次數_12ML,0) AS FB_TXN_PROD_12ML,
        ROUND(交易天數_12ML,0) AS FB_TXN_DAY_12ML,
        ROUND(交易金額_12ML,0) AS FB_TXN_AMT_12ML,
        ROUND(買入次數_12ML,0) AS FB_BUY_PROD_12ML,
        ROUND(買入天數_12ML,0) AS FB_BUY_DAY_12ML,
        ROUND(買入金額_12ML,0) AS FB_BUY_AMT_12ML,
        ROUND(賣出次數_12ML,0) AS FB_SEL_PROD_12ML,
        ROUND(賣出天數_12ML,0) AS FB_SEL_DAY_12ML,
        ROUND(賣出金額_12ML,0) AS FB_SEL_AMT_12ML,

        ROUND(NVL(交易次數_M, 0) - NVL(交易次數_ML, 0),0) AS FB_TXN_PROD_M_MDIFF,
        ROUND(NVL(交易天數_M, 0) - NVL(交易天數_ML, 0),0) AS FB_TXN_DAY_M_MDIFF,
        ROUND(NVL(交易金額_M, 0) - NVL(交易金額_ML, 0),0) AS FB_TXN_AMT_M_MDIFF,
        ROUND(NVL(買入次數_M, 0) - NVL(買入次數_ML, 0),0) AS FB_BUY_PROD_M_MDIFF,
        ROUND(NVL(買入天數_M, 0) - NVL(買入天數_ML, 0),0) AS FB_BUY_DAY_M_MDIFF,
        ROUND(NVL(買入金額_M, 0) - NVL(買入金額_ML, 0),0) AS FB_BUY_AMT_M_MDIFF,
        ROUND(NVL(賣出次數_M, 0) - NVL(賣出次數_ML, 0),0) AS FB_SEL_PROD_M_MDIFF,
        ROUND(NVL(賣出天數_M, 0) - NVL(賣出天數_ML, 0),0) AS FB_SEL_DAY_M_MDIFF,
        ROUND(NVL(賣出金額_M, 0) - NVL(賣出金額_ML, 0),0) AS FB_SEL_AMT_M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_ML, 0) <> 0  THEN (NVL(交易次數_M, 0) / NVL(交易次數_ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_PROD_M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_ML, 0) <> 0  THEN (NVL(交易天數_M, 0) / NVL(交易天數_ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_DAY_M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_ML, 0) <> 0  THEN (NVL(交易金額_M, 0) / NVL(交易金額_ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_AMT_M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_ML, 0) <> 0  THEN (NVL(買入次數_M, 0) / NVL(買入次數_ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_PROD_M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_ML, 0) <> 0  THEN (NVL(買入天數_M, 0) / NVL(買入天數_ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_DAY_M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_ML, 0) <> 0  THEN (NVL(買入金額_M, 0) / NVL(買入金額_ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_AMT_M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_ML, 0) <> 0  THEN (NVL(賣出次數_M, 0) / NVL(賣出次數_ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_PROD_M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_ML, 0) <> 0  THEN (NVL(賣出天數_M, 0) / NVL(賣出天數_ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_DAY_M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_ML, 0) <> 0  THEN (NVL(賣出金額_M, 0) / NVL(賣出金額_ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_AMT_M_RDIFF,

        ROUND(NVL(交易次數_3M, 0) - NVL(交易次數_3ML, 0),0) AS FB_TXN_PROD_3M_MDIFF,
        ROUND(NVL(交易天數_3M, 0) - NVL(交易天數_3ML, 0),0) AS FB_TXN_DAY_3M_MDIFF,
        ROUND(NVL(交易金額_3M, 0) - NVL(交易金額_3ML, 0),0) AS FB_TXN_AMT_3M_MDIFF,
        ROUND(NVL(買入次數_3M, 0) - NVL(買入次數_3ML, 0),0) AS FB_BUY_PROD_3M_MDIFF,
        ROUND(NVL(買入天數_3M, 0) - NVL(買入天數_3ML, 0),0) AS FB_BUY_DAY_3M_MDIFF,
        ROUND(NVL(買入金額_3M, 0) - NVL(買入金額_3ML, 0),0) AS FB_BUY_AMT_3M_MDIFF,
        ROUND(NVL(賣出次數_3M, 0) - NVL(賣出次數_3ML, 0),0) AS FB_SEL_PROD_3M_MDIFF,
        ROUND(NVL(賣出天數_3M, 0) - NVL(賣出天數_3ML, 0),0) AS FB_SEL_DAY_3M_MDIFF,
        ROUND(NVL(賣出金額_3M, 0) - NVL(賣出金額_3ML, 0),0) AS FB_SEL_AMT_3M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_3ML, 0) <> 0  THEN (NVL(交易次數_3M, 0) / NVL(交易次數_3ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_PROD_3M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_3ML, 0) <> 0  THEN (NVL(交易天數_3M, 0) / NVL(交易天數_3ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_DAY_3M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_3ML, 0) <> 0  THEN (NVL(交易金額_3M, 0) / NVL(交易金額_3ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_AMT_3M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_3ML, 0) <> 0  THEN (NVL(買入次數_3M, 0) / NVL(買入次數_3ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_PROD_3M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_3ML, 0) <> 0  THEN (NVL(買入天數_3M, 0) / NVL(買入天數_3ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_DAY_3M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_3ML, 0) <> 0  THEN (NVL(買入金額_3M, 0) / NVL(買入金額_3ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_AMT_3M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_3ML, 0) <> 0  THEN (NVL(賣出次數_3M, 0) / NVL(賣出次數_3ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_PROD_3M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_3ML, 0) <> 0  THEN (NVL(賣出天數_3M, 0) / NVL(賣出天數_3ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_DAY_3M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_3ML, 0) <> 0  THEN (NVL(賣出金額_3M, 0) / NVL(賣出金額_3ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_AMT_3M_RDIFF,

        ROUND(NVL(交易次數_6M, 0) - NVL(交易次數_6ML, 0),0) AS FB_TXN_PROD_6M_MDIFF,
        ROUND(NVL(交易天數_6M, 0) - NVL(交易天數_6ML, 0),0) AS FB_TXN_DAY_6M_MDIFF,
        ROUND(NVL(交易金額_6M, 0) - NVL(交易金額_6ML, 0),0) AS FB_TXN_AMT_6M_MDIFF,
        ROUND(NVL(買入次數_6M, 0) - NVL(買入次數_6ML, 0),0) AS FB_BUY_PROD_6M_MDIFF,
        ROUND(NVL(買入天數_6M, 0) - NVL(買入天數_6ML, 0),0) AS FB_BUY_DAY_6M_MDIFF,
        ROUND(NVL(買入金額_6M, 0) - NVL(買入金額_6ML, 0),0) AS FB_BUY_AMT_6M_MDIFF,
        ROUND(NVL(賣出次數_6M, 0) - NVL(賣出次數_6ML, 0),0) AS FB_SEL_PROD_6M_MDIFF,
        ROUND(NVL(賣出天數_6M, 0) - NVL(賣出天數_6ML, 0),0) AS FB_SEL_DAY_6M_MDIFF,
        ROUND(NVL(賣出金額_6M, 0) - NVL(賣出金額_6ML, 0),0) AS FB_SEL_AMT_6M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_6ML, 0) <> 0  THEN (NVL(交易次數_6M, 0) / NVL(交易次數_6ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_PROD_6M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_6ML, 0) <> 0  THEN (NVL(交易天數_6M, 0) / NVL(交易天數_6ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_DAY_6M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_6ML, 0) <> 0  THEN (NVL(交易金額_6M, 0) / NVL(交易金額_6ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_AMT_6M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_6ML, 0) <> 0  THEN (NVL(買入次數_6M, 0) / NVL(買入次數_6ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_PROD_6M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_6ML, 0) <> 0  THEN (NVL(買入天數_6M, 0) / NVL(買入天數_6ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_DAY_6M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_6ML, 0) <> 0  THEN (NVL(買入金額_6M, 0) / NVL(買入金額_6ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_AMT_6M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_6ML, 0) <> 0  THEN (NVL(賣出次數_6M, 0) / NVL(賣出次數_6ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_PROD_6M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_6ML, 0) <> 0  THEN (NVL(賣出天數_6M, 0) / NVL(賣出天數_6ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_DAY_6M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_6ML, 0) <> 0  THEN (NVL(賣出金額_6M, 0) / NVL(賣出金額_6ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_AMT_6M_RDIFF,

        ROUND(NVL(交易次數_12M, 0) - NVL(交易次數_12ML, 0),0) AS FB_TXN_PROD_12M_MDIFF,
        ROUND(NVL(交易天數_12M, 0) - NVL(交易天數_12ML, 0),0) AS FB_TXN_DAY_12M_MDIFF,
        ROUND(NVL(交易金額_12M, 0) - NVL(交易金額_12ML, 0),0) AS FB_TXN_AMT_12M_MDIFF,
        ROUND(NVL(買入次數_12M, 0) - NVL(買入次數_12ML, 0),0) AS FB_BUY_PROD_12M_MDIFF,
        ROUND(NVL(買入天數_12M, 0) - NVL(買入天數_12ML, 0),0) AS FB_BUY_DAY_12M_MDIFF,
        ROUND(NVL(買入金額_12M, 0) - NVL(買入金額_12ML, 0),0) AS FB_BUY_AMT_12M_MDIFF,
        ROUND(NVL(賣出次數_12M, 0) - NVL(賣出次數_12ML, 0),0) AS FB_SEL_PROD_12M_MDIFF,
        ROUND(NVL(賣出天數_12M, 0) - NVL(賣出天數_12ML, 0),0) AS FB_SEL_DAY_12M_MDIFF,
        ROUND(NVL(賣出金額_12M, 0) - NVL(賣出金額_12ML, 0),0) AS FB_SEL_AMT_12M_MDIFF,

        ROUND(CASE WHEN NVL(交易次數_12ML, 0) <> 0  THEN (NVL(交易次數_12M, 0) / NVL(交易次數_12ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_PROD_12M_RDIFF,
        ROUND(CASE WHEN NVL(交易天數_12ML, 0) <> 0  THEN (NVL(交易天數_12M, 0) / NVL(交易天數_12ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_DAY_12M_RDIFF,
        ROUND(CASE WHEN NVL(交易金額_12ML, 0) <> 0  THEN (NVL(交易金額_12M, 0) / NVL(交易金額_12ML, 0) - 1) ELSE 0 END,4) AS FB_TXN_AMT_12M_RDIFF,
        ROUND(CASE WHEN NVL(買入次數_12ML, 0) <> 0  THEN (NVL(買入次數_12M, 0) / NVL(買入次數_12ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_PROD_12M_RDIFF,
        ROUND(CASE WHEN NVL(買入天數_12ML, 0) <> 0  THEN (NVL(買入天數_12M, 0) / NVL(買入天數_12ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_DAY_12M_RDIFF,
        ROUND(CASE WHEN NVL(買入金額_12ML, 0) <> 0  THEN (NVL(買入金額_12M, 0) / NVL(買入金額_12ML, 0) - 1) ELSE 0 END,4) AS FB_BUY_AMT_12M_RDIFF,
        ROUND(CASE WHEN NVL(賣出次數_12ML, 0) <> 0  THEN (NVL(賣出次數_12M, 0) / NVL(賣出次數_12ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_PROD_12M_RDIFF,
        ROUND(CASE WHEN NVL(賣出天數_12ML, 0) <> 0  THEN (NVL(賣出天數_12M, 0) / NVL(賣出天數_12ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_DAY_12M_RDIFF,
        ROUND(CASE WHEN NVL(賣出金額_12ML, 0) <> 0  THEN (NVL(賣出金額_12M, 0) / NVL(賣出金額_12ML, 0) - 1) ELSE 0 END,4) AS FB_SEL_AMT_12M_RDIFF

FROM TEMPFB2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID
;
----------------------------------交易_基金---------------------------------------------------
INSERT INTO DS_SEC.CF_TXN_FD
WITH TEMPFD1
AS (
SELECT PARTY_ID_MASK CUSTOMER_ID
      ,TXN_YYYYMM AS YYYYMM
      ,COUNT(*) AS 交易次數
      ,COUNT(DISTINCT TXN_DATE) AS 交易天數
      ,SUM(TXN_AMT_TWD)AS 交易金額
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN 1 ELSE 0 END) AS 買入次數
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '001' THEN TXN_DATE ELSE NULL END) AS 買入天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '001' THEN TXN_AMT_TWD ELSE 0 END) AS 買入金額
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN 1 ELSE 0 END) AS 賣出次數
      ,COUNT(DISTINCT CASE WHEN BUY_SELL_CODE = '002' THEN TXN_DATE ELSE NULL END) AS 賣出天數
      ,SUM(CASE WHEN BUY_SELL_CODE = '002' THEN TXN_AMT_TWD ELSE 0 END) AS 賣出金額
FROM DM_S_VIEW.M_AT_FUND_TXN A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
ON A.PARTY_ID = B.PARTY_ID
WHERE TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK,TXN_YYYYMM
), TEMPFD2
AS (
SELECT CUSTOMER_ID
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易次數 ELSE 0 END)交易次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易天數 ELSE 0 END)交易天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 交易金額 ELSE 0 END)交易金額M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 買入次數 ELSE 0 END)買入次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 買入天數 ELSE 0 END)買入天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 買入金額 ELSE 0 END)買入金額M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 賣出次數 ELSE 0 END)賣出次數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 賣出天數 ELSE 0 END)賣出天數M
      ,SUM(CASE WHEN YYYYMM = :ym THEN 賣出金額 ELSE 0 END)賣出金額M
      
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數L
      ,SUM(CASE WHEN YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額L
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END)買入次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END)買入天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END)買入金額3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END)賣出次數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END)賣出天數3M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END)賣出金額3M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數3ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額3ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END)買入次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END)買入天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END)買入金額6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END)賣出次數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END)賣出天數6M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END)賣出金額6M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數6ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額6ML
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易次數 ELSE 0 END)交易次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易天數 ELSE 0 END)交易天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 交易金額 ELSE 0 END)交易金額12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入次數 ELSE 0 END)買入次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入天數 ELSE 0 END)買入天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 買入金額 ELSE 0 END)買入金額12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出次數 ELSE 0 END)賣出次數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出天數 ELSE 0 END)賣出天數12M
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 賣出金額 ELSE 0 END)賣出金額12M
      
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易次數 ELSE 0 END)交易次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易天數 ELSE 0 END)交易天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 交易金額 ELSE 0 END)交易金額12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入次數 ELSE 0 END)買入次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入天數 ELSE 0 END)買入天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 買入金額 ELSE 0 END)買入金額12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出次數 ELSE 0 END)賣出次數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出天數 ELSE 0 END)賣出天數12ML
      ,SUM(CASE WHEN YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN 賣出金額 ELSE 0 END)賣出金額12ML
FROM TEMPFD1
GROUP BY CUSTOMER_ID
) 

SELECT
