    FD_SEL_AMT_3M_RDIFF,
    FD_TXN_PROD_6M,
    FD_TXN_PROD_6M_MDIFF,
    FD_TXN_PROD_6M_RDIFF,
    FD_TXN_DAY_6M,
    FD_TXN_DAY_6M_MDIFF,
    FD_TXN_DAY_6M_RDIFF,
    FD_TXN_AMT_6M,
