    AP_SEL_DAY_6M_MDIFF,
    AP_SEL_DAY_6M_RDIFF,
    AP_SEL_AMT_6M,
    AP_SEL_AMT_6M_MDIFF,
    AP_SEL_AMT_6M_RDIFF,
    AP_TXN_PROD_12M,
    AP_TXN_PROD_12M_MDIFF,
    AP_TXN_PROD_12M_RDIFF,
    AP_TXN_DAY_12M,
    AP_TXN_DAY_12M_MDIFF,
    AP_TXN_DAY_12M_RDIFF,
    AP_TXN_AMT_12M,
    AP_TXN_AMT_12M_MDIFF,
    AP_TXN_AMT_12M_RDIFF,
    AP_BUY_PROD_12M,
    AP_BUY_PROD_12M_MDIFF,
    AP_BUY_PROD_12M_RDIFF,
    AP_BUY_DAY_12M,
    AP_BUY_DAY_12M_MDIFF,
    AP_BUY_DAY_12M_RDIFF,
    AP_BUY_AMT_12M,
    AP_BUY_AMT_12M_MDIFF,
    AP_BUY_AMT_12M_RDIFF,
    AP_SEL_PROD_12M,
    AP_SEL_PROD_12M_MDIFF,
    AP_SEL_PROD_12M_RDIFF,
    AP_SEL_DAY_12M,
    AP_SEL_DAY_12M_MDIFF,
    AP_SEL_DAY_12M_RDIFF,
    AP_SEL_AMT_12M,
    AP_SEL_AMT_12M_MDIFF,
    AP_SEL_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
SELECT CUSTOMER_ID
      , :ym AS YYYYMM
      , ROUND(交易次數M,0) AS AP_TXN_PROD_M
      , ROUND(交易次數M-交易次數L,0) AS AP_TXN_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易次數L,0)>0 THEN (NVL(交易次數M,0)/NVL(交易次數L,0))-1 ELSE 0 END,4) AS AP_TXN_PROD_M_RDIFF
      , ROUND(交易天數M,0) AS AP_TXN_DAY_M 
      , ROUND(交易天數M-交易天數L,0) AS AP_TXN_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數L,0)>0 THEN (NVL(交易天數M,0)/NVL(交易天數L,0))-1 ELSE 0 END,4) AS AP_TXN_DAY_M_RDIFF
      , ROUND(交易金額M,0) AS AP_TXN_AMT_M
      , ROUND(交易金額M-交易金額L,0) AS AP_TXN_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(交易金額L,0)>0 THEN (NVL(交易金額M,0)/NVL(交易金額L,0))-1 ELSE 0 END,4) AS AP_TXN_AMT_M_RDIFF 
      , ROUND(買入次數M,0) AS AP_BUY_PROD_M 
      , ROUND(買入次數M-買入次數L,0) AS AP_BUY_PROD_M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數L,0)>0 THEN (NVL(買入次數M,0)/NVL(買入次數L,0))-1 ELSE 0 END,4) AS AP_BUY_PROD_M_RDIFF
      , ROUND(買入天數M,0) AS AP_BUY_DAY_M
      , ROUND(買入天數M-買入天數L,0) AS AP_BUY_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數L,0)>0 THEN (NVL(買入天數M,0)/NVL(買入天數L,0))-1 ELSE 0 END,4) AS AP_BUY_DAY_M_RDIFF
      , ROUND(買入金額M,0) AS AP_BUY_AMT_M
      , ROUND(買入金額M-買入金額L,0) AS AP_BUY_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(買入金額L,0)>0 THEN (NVL(買入金額M,0)/NVL(買入金額L,0))-1 ELSE 0 END,4) AS AP_BUY_AMT_M_RDIFF
      , ROUND(賣出次數M,0) AS AP_SEL_PROD_M
      , ROUND(賣出次數M-賣出次數L,0) AS AP_SEL_PROD_M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數L,0)>0 THEN (NVL(賣出次數M,0)/NVL(賣出次數L,0))-1 ELSE 0 END,4) AS AP_SEL_PROD_M_RDIFF 
      , ROUND(賣出天數M,0) AS AP_SEL_DAY_M
      , ROUND(賣出天數M-賣出天數L,0) AS AP_SEL_DAY_M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數L,0)>0 THEN (NVL(賣出天數M,0)/NVL(賣出天數L,0))-1 ELSE 0 END,4) AS AP_SEL_DAY_M_RDIFF 
      , ROUND(賣出金額M,0) AS AP_SEL_AMT_M 
      , ROUND(賣出金額M-賣出金額L,0) AS AP_SEL_AMT_M_MDIFF
      , ROUND(CASE WHEN NVL(賣出金額L,0)>0 THEN (NVL(賣出金額M,0)/NVL(賣出金額L,0))-1 ELSE 0 END,4) AS AP_SEL_AMT_M_RDIFF 
      
      , ROUND(交易次數3M,0) AS AP_TXN_PROD_3M 
      , ROUND(交易次數3M-交易次數3ML,0) AS AP_TXN_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數3ML,0)>0 THEN (NVL(交易次數3M,0)/NVL(交易次數3ML,0))-1 ELSE 0 END,4) AS AP_TXN_PROD_3M_RDIFF 
      , ROUND(交易天數3M,0) AS AP_TXN_DAY_3M 
      , ROUND(交易天數3M-交易天數3ML,0) AS AP_TXN_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數3ML,0)>0 THEN (NVL(交易天數3M,0)/NVL(交易天數3ML,0))-1 ELSE 0 END,4) AS AP_TXN_DAY_3M_RDIFF 
      , ROUND(交易金額3M,0) AS AP_TXN_AMT_3M 
      , ROUND(交易金額3M-交易金額3ML,0) AS AP_TXN_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額3ML,0)>0 THEN (NVL(交易金額3M,0)/NVL(交易金額3ML,0))-1 ELSE 0 END,4) AS AP_TXN_AMT_3M_RDIFF 
      , ROUND(買入次數3M,0) AS AP_BUY_PROD_3M 
      , ROUND(買入次數3M-買入次數3ML,0) AS AP_BUY_PROD_3M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數3ML,0)>0 THEN (NVL(買入次數3M,0)/NVL(買入次數3ML,0))-1 ELSE 0 END,4) AS AP_BUY_PROD_3M_RDIFF 
      , ROUND(買入天數3M,0) AS AP_BUY_DAY_3M 
      , ROUND(買入天數3M-買入天數3ML,0) AS AP_BUY_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數3ML,0)>0 THEN (NVL(買入天數3M,0)/NVL(買入天數3ML,0))-1 ELSE 0 END,4) AS AP_BUY_DAY_3M_RDIFF 
      , ROUND(買入金額3M,0) AS AP_BUY_AMT_3M 
      , ROUND(買入金額3M-買入金額3ML,0) AS AP_BUY_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額3ML,0)>0 THEN (NVL(買入金額3M,0)/NVL(買入金額3ML,0))-1 ELSE 0 END,4) AS AP_BUY_AMT_3M_RDIFF 
      , ROUND(賣出次數3M,0) AS AP_SEL_PROD_3M 
      , ROUND(賣出次數3M-賣出次數3ML,0) AS AP_SEL_PROD_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數3ML,0)>0 THEN (NVL(賣出次數3M,0)/NVL(賣出次數3ML,0))-1 ELSE 0 END,4) AS AP_SEL_PROD_3M_RDIFF 
      , ROUND(賣出天數3M,0) AS AP_SEL_DAY_3M 
      , ROUND(賣出天數3M-賣出天數3ML,0) AS AP_SEL_DAY_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數3ML,0)>0 THEN (NVL(賣出天數3M,0)/NVL(賣出天數3ML,0))-1 ELSE 0 END,4) AS AP_SEL_DAY_3M_RDIFF 
      , ROUND(賣出金額3M,0) AS AP_SEL_AMT_3M 
      , ROUND(賣出金額3M-賣出金額3ML,0) AS AP_SEL_AMT_3M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額3ML,0)>0 THEN (NVL(賣出金額3M,0)/NVL(賣出金額3ML,0))-1 ELSE 0 END,4) AS AP_SEL_AMT_3M_RDIFF 
      
      , ROUND(交易次數6M,0) AS AP_TXN_PROD_6M 
      , ROUND(交易次數6M-交易次數6ML,0) AS AP_TXN_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數6ML,0)>0 THEN (NVL(交易次數6M,0)/NVL(交易次數6ML,0))-1 ELSE 0 END,4) AS AP_TXN_PROD_6M_RDIFF 
      , ROUND(交易天數6M,0) AS AP_TXN_DAY_6M 
      , ROUND(交易天數6M-交易天數6ML,0) AS AP_TXN_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數6ML,0)>0 THEN (NVL(交易天數6M,0)/NVL(交易天數6ML,0))-1 ELSE 0 END,4) AS AP_TXN_DAY_6M_RDIFF 
      , ROUND(交易金額6M,0) AS AP_TXN_AMT_6M 
      , ROUND(交易金額6M-交易金額6ML,0) AS AP_TXN_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額6ML,0)>0 THEN (NVL(交易金額6M,0)/NVL(交易金額6ML,0))-1 ELSE 0 END,4) AS AP_TXN_AMT_6M_RDIFF 
      , ROUND(買入次數6M,0) AS AP_BUY_PROD_6M 
      , ROUND(買入次數6M-買入次數6ML,0) AS AP_BUY_PROD_6M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數6ML,0)>0 THEN (NVL(買入次數6M,0)/NVL(買入次數6ML,0))-1 ELSE 0 END,4) AS AP_BUY_PROD_6M_RDIFF 
      , ROUND(買入天數6M,0) AS AP_BUY_DAY_6M 
      , ROUND(買入天數6M-買入天數6ML,0) AS AP_BUY_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數6ML,0)>0 THEN (NVL(買入天數6M,0)/NVL(買入天數6ML,0))-1 ELSE 0 END,4) AS AP_BUY_DAY_6M_RDIFF 
      , ROUND(買入金額6M,0) AS AP_BUY_AMT_6M 
      , ROUND(買入金額6M-買入金額6ML,0) AS AP_BUY_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額6ML,0)>0 THEN (NVL(買入金額6M,0)/NVL(買入金額6ML,0))-1 ELSE 0 END,4) AS AP_BUY_AMT_6M_RDIFF 
      , ROUND(賣出次數6M,0) AS AP_SEL_PROD_6M 
      , ROUND(賣出次數6M-賣出次數6ML,0) AS AP_SEL_PROD_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數6ML,0)>0 THEN (NVL(賣出次數6M,0)/NVL(賣出次數6ML,0))-1 ELSE 0 END,4) AS AP_SEL_PROD_6M_RDIFF 
      , ROUND(賣出天數6M,0) AS AP_SEL_DAY_6M 
      , ROUND(賣出天數6M-賣出天數6ML,0) AS AP_SEL_DAY_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數6ML,0)>0 THEN (NVL(賣出天數6M,0)/NVL(賣出天數6ML,0))-1 ELSE 0 END,4) AS AP_SEL_DAY_6M_RDIFF 
      , ROUND(賣出金額6M,0) AS AP_SEL_AMT_6M 
      , ROUND(賣出金額6M-賣出金額6ML,0) AS AP_SEL_AMT_6M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額6ML,0)>0 THEN (NVL(賣出金額6M,0)/NVL(賣出金額6ML,0))-1 ELSE 0 END,4) AS AP_SEL_AMT_6M_RDIFF 
      
      , ROUND(交易次數12M,0) AS AP_TXN_PROD_12M 
      , ROUND(交易次數12M-交易次數12ML,0) AS AP_TXN_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(交易次數12ML,0)>0 THEN (NVL(交易次數12M,0)/NVL(交易次數12ML,0))-1 ELSE 0 END,4) AS AP_TXN_PROD_12M_RDIFF 
      , ROUND(交易天數12M,0) AS AP_TXN_DAY_12M 
      , ROUND(交易天數12M-交易天數12ML,0) AS AP_TXN_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易天數12ML,0)>0 THEN (NVL(交易天數12M,0)/NVL(交易天數12ML,0))-1 ELSE 0 END,4) AS AP_TXN_DAY_12M_RDIFF 
      , ROUND(交易金額12M,0) AS AP_TXN_AMT_12M 
      , ROUND(交易金額12M-交易金額12ML,0) AS AP_TXN_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(交易金額12ML,0)>0 THEN (NVL(交易金額12M,0)/NVL(交易金額12ML,0))-1 ELSE 0 END,4) AS AP_TXN_AMT_12M_RDIFF 
      , ROUND(買入次數12M,0) AS AP_BUY_PROD_12M 
      , ROUND(買入次數12M-買入次數12ML,0) AS AP_BUY_PROD_12M_MDIFF
      , ROUND(CASE WHEN NVL(買入次數12ML,0)>0 THEN (NVL(買入次數12M,0)/NVL(買入次數12ML,0))-1 ELSE 0 END,4) AS AP_BUY_PROD_12M_RDIFF 
      , ROUND(買入天數12M,0) AS AP_BUY_DAY_12M 
      , ROUND(買入天數12M-買入天數12ML,0) AS AP_BUY_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(買入天數12ML,0)>0 THEN (NVL(買入天數12M,0)/NVL(買入天數12ML,0))-1 ELSE 0 END,4) AS AP_BUY_DAY_12M_RDIFF 
      , ROUND(買入金額12M,0) AS AP_BUY_AMT_12M 
      , ROUND(買入金額12M-買入金額12ML,0) AS AP_BUY_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(買入金額12ML,0)>0 THEN (NVL(買入金額12M,0)/NVL(買入金額12ML,0))-1 ELSE 0 END,4) AS AP_BUY_AMT_12M_RDIFF 
      , ROUND(賣出次數12M,0) AS AP_SEL_PROD_12M 
      , ROUND(賣出次數12M-賣出次數12ML,0) AS AP_SEL_PROD_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出次數12ML,0)>0 THEN (NVL(賣出次數12M,0)/NVL(賣出次數12ML,0))-1 ELSE 0 END,4) AS AP_SEL_PROD_12M_RDIFF 
      , ROUND(賣出天數12M,0) AS AP_SEL_DAY_12M 
      , ROUND(賣出天數12M-賣出天數12ML,0) AS AP_SEL_DAY_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出天數12ML,0)>0 THEN (NVL(賣出天數12M,0)/NVL(賣出天數12ML,0))-1 ELSE 0 END,4) AS AP_SEL_DAY_12M_RDIFF 
      , ROUND(賣出金額12M,0) AS AP_SEL_AMT_12M 
      , ROUND(賣出金額12M-賣出金額12ML,0) AS AP_SEL_AMT_12M_MDIFF 
      , ROUND(CASE WHEN NVL(賣出金額12ML,0)>0 THEN (NVL(賣出金額12M,0)/NVL(賣出金額12ML,0))-1 ELSE 0 END,4) AS AP_SEL_AMT_12M_RDIFF 
FROM TEMPAP_2)B
ON A.CUSTOMER_ID  = B.CUSTOMER_ID AND A.YYYYMM = B.YYYYMM
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID
;
/*******************************************************************************************/

----------------------------------客戶資產-----------------------------------------------
INSERT INTO DS_SEC.CF_AUM
WITH TEMP_2AUM1 AS (
SELECT DISTINCT A.CUSTOMER_ID
        ,NVL(台股庫存M,0)+NVL(融資庫存M,0)+NVL(融券庫存M,0)+NVL(不限用途庫存M,0)+NVL(雙向借券庫存M,0)+NVL(海外股票庫存M,0)+NVL(海外債券庫存M,0)+NVL(基金庫存M,0)+NVL(結構型商品庫存M,0)+NVL(期貨庫存M,0) AS AUM_M
        ,NVL(台股庫存L,0)+NVL(融資庫存L,0)+NVL(融券庫存L,0)+NVL(不限用途庫存L,0)+NVL(雙向借券庫存L,0)+NVL(海外股票庫存L,0)+NVL(海外債券庫存L,0)+NVL(基金庫存L,0)+NVL(結構型商品庫存L,0)+NVL(期貨庫存L,0) AS AUM_L
        ,NVL(台股庫存3M,0)+NVL(融資庫存3M,0)+NVL(融券庫存3M,0)+NVL(不限用途庫存3M,0)+NVL(雙向借券庫存3M,0)+NVL(海外股票庫存3M,0)+NVL(海外債券庫存3M,0)+NVL(基金庫存3M,0)+NVL(結構型商品庫存3M,0)+NVL(期貨庫存3M,0) AS AUM_3M
        ,NVL(台股庫存6M,0)+NVL(融資庫存6M,0)+NVL(融券庫存6M,0)+NVL(不限用途庫存6M,0)+NVL(雙向借券庫存6M,0)+NVL(海外股票庫存6M,0)+NVL(海外債券庫存6M,0)+NVL(基金庫存6M,0)+NVL(結構型商品庫存6M,0)+NVL(期貨庫存6M,0) AS AUM_6M
        ,NVL(台股庫存12M,0)+NVL(融資庫存12M,0)+NVL(融券庫存12M,0)+NVL(不限用途庫存12M,0)+NVL(雙向借券庫存12M,0)+NVL(海外股票庫存12M,0)+NVL(海外債券庫存12M,0)+NVL(基金庫存12M,0)+NVL(結構型商品庫存12M,0)+NVL(期貨庫存12M,0) AS AUM_12M
        ,台股庫存M
        ,台股庫存L
        ,台股庫存3M
        ,台股庫存6M
        ,台股庫存12M
        ,融資庫存M
        ,融資庫存L
        ,融資庫存3M
        ,融資庫存6M
        ,融資庫存12M
        ,融券庫存M
        ,融券庫存L
        ,融券庫存3M
        ,融券庫存6M
        ,融券庫存12M
        ,定期定額庫存M
        ,定期定額庫存L
        ,定期定額庫存3M
        ,定期定額庫存6M
        ,定期定額庫存12M
        ,不限用途庫存M
        ,不限用途庫存L
        ,不限用途庫存3M
        ,不限用途庫存6M
        ,不限用途庫存12M
        ,雙向借券庫存M
        ,雙向借券庫存L
        ,雙向借券庫存3M
        ,雙向借券庫存6M
        ,雙向借券庫存12M
        ,海外股票庫存M
        ,海外股票庫存L
        ,海外股票庫存3M
        ,海外股票庫存6M
        ,海外股票庫存12M
        ,海外債券庫存M
        ,海外債券庫存L
        ,海外債券庫存3M
        ,海外債券庫存6M
        ,海外債券庫存12M
        ,基金庫存M
        ,基金庫存L
        ,基金庫存3M
        ,基金庫存6M
        ,基金庫存12M
        ,結構型商品庫存M
        ,結構型商品庫存L
        ,結構型商品庫存3M
        ,結構型商品庫存6M
        ,結構型商品庫存12M
        ,期貨庫存M
        ,期貨庫存L
        ,期貨庫存3M
        ,期貨庫存6M
        ,期貨庫存12M
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
-- 台股現股庫存  
SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END)台股庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)台股庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)台股庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)台股庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)台股庫存12M
        FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
        LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
        ON A.PARTY_ID = B.PARTY_ID
        WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('110')
        GROUP BY PARTY_ID_MASK)AUMST
 ON AUMST.CUSTOMER_ID = A.CUSTOMER_ID
LEFT JOIN (   
--台股融資庫存
   SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN NET_MARGIN_LOAN_AMT_TWD ELSE 0 END)融資庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN NET_MARGIN_LOAN_AMT_TWD ELSE 0 END)融資庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN NET_MARGIN_LOAN_AMT_TWD ELSE 0 END)融資庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN NET_MARGIN_LOAN_AMT_TWD ELSE 0 END)融資庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN NET_MARGIN_LOAN_AMT_TWD ELSE 0 END)融資庫存12M
        FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
        LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
        ON A.PARTY_ID = B.PARTY_ID
        WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND NET_MARGIN_LOAN_AMT_TWD>0
        GROUP BY PARTY_ID_MASK)AUMMT
ON AUMMT.CUSTOMER_ID = A.CUSTOMER_ID
LEFT JOIN (
--台股融券庫存
    SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN NET_STOCK_LOAN_AMT_TWD ELSE 0 END)融券庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN NET_STOCK_LOAN_AMT_TWD ELSE 0 END)融券庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN NET_STOCK_LOAN_AMT_TWD ELSE 0 END)融券庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN NET_STOCK_LOAN_AMT_TWD ELSE 0 END)融券庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN NET_STOCK_LOAN_AMT_TWD ELSE 0 END)融券庫存12M
        FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
        LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
        ON A.PARTY_ID = B.PARTY_ID
        WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND NET_STOCK_LOAN_AMT_TWD>0
        GROUP BY PARTY_ID_MASK )AUMSS
ON AUMSS.CUSTOMER_ID = A.CUSTOMER_ID
     
LEFT JOIN (
--台股定期定額庫存
    SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN DC_BAL_AMT_TWD ELSE 0 END)定期定額庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN DC_BAL_AMT_TWD ELSE 0 END)定期定額庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN DC_BAL_AMT_TWD ELSE 0 END)定期定額庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN DC_BAL_AMT_TWD ELSE 0 END)定期定額庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN DC_BAL_AMT_TWD ELSE 0 END)定期定額庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND DC_BAL_AMT_TWD>0
    GROUP BY PARTY_ID_MASK )AUMSIP
ON AUMSIP.CUSTOMER_ID = A.CUSTOMER_ID
       
LEFT JOIN (   
--不限用途庫存(擔保品)  
   SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN URUL_LOAN_BAL_AMT ELSE 0 END)不限用途庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN URUL_LOAN_BAL_AMT ELSE 0 END)不限用途庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN URUL_LOAN_BAL_AMT ELSE 0 END)不限用途庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN URUL_LOAN_BAL_AMT ELSE 0 END)不限用途庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN URUL_LOAN_BAL_AMT ELSE 0 END)不限用途庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('160')
    GROUP BY PARTY_ID_MASK)AUMUU
ON AUMUU.CUSTOMER_ID = A.CUSTOMER_ID
     
LEFT JOIN (     
     --雙向借券庫存
   SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END)雙向借券庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)雙向借券庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)雙向借券庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)雙向借券庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)雙向借券庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('150')
    GROUP BY PARTY_ID_MASK)AUMDD
ON AUMDD.CUSTOMER_ID = A.CUSTOMER_ID
     
LEFT JOIN (     
     --海外股票庫存
    SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END)海外股票庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外股票庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外股票庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外股票庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外股票庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('210')
    GROUP BY PARTY_ID_MASK)AUMFS
ON AUMFS.CUSTOMER_ID = A.CUSTOMER_ID
     
LEFT JOIN (    
     --海外債券庫存
   SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END)海外債券庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外債券庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外債券庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外債券庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)海外債券庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('230')
    GROUP BY PARTY_ID_MASK)AUMFT
ON AUMFT.CUSTOMER_ID = A.CUSTOMER_ID
       
LEFT JOIN (   
     --基金券庫存
    SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END)基金庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)基金庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)基金庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)基金庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)基金庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('120','220','420')
    GROUP BY PARTY_ID_MASK)AUMFU
ON AUMFU.CUSTOMER_ID = A.CUSTOMER_ID
     
LEFT JOIN (   
     --結構型商品庫存
    SELECT PARTY_ID_MASK AS CUSTOMER_ID
         ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BAL_AMT_TWD ELSE 0 END)結構型商品庫存M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)結構型商品庫存L
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)結構型商品庫存3M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)結構型商品庫存6M
         ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN BAL_AMT_TWD ELSE 0 END)結構型商品庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('240','540')
    GROUP BY PARTY_ID_MASK)AUMFNC
ON AUMFNC.CUSTOMER_ID = A.CUSTOMER_ID

LEFT JOIN (   
     --期貨庫存
    SELECT PARTY_ID_MASK AS CUSTOMER_ID
             ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN EQUITY_AMT_TWD ELSE 0 END)期貨庫存M
             ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN EQUITY_AMT_TWD ELSE 0 END)期貨庫存L
             ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN EQUITY_AMT_TWD ELSE 0 END)期貨庫存3M
             ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN EQUITY_AMT_TWD ELSE 0 END)期貨庫存6M
             ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN EQUITY_AMT_TWD ELSE 0 END)期貨庫存12M
    FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
    LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
    ON A.PARTY_ID = B.PARTY_ID
    WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM')) AND PROD_MTYPE_CODE IN ('3CP','3FS')
    GROUP BY PARTY_ID_MASK)AUMXX
ON AUMXX.CUSTOMER_ID = A.CUSTOMER_ID   
WHERE A.YYYYMM = :ym
)

SELECT  CUSTOMER_ID
        , :ym AS YYYYMM
        , ROUND(NVL(AUM_M,0),0) AP_AUM_M
        , ROUND(NVL(AUM_M,0)-NVL(AUM_L,0),0) AP_AUM_M_MDIFF
        , ROUND(NVL(AUM_M,0)-NVL(AUM_3M,0),0) AP_AUM_3M_MDIFF
        , ROUND(NVL(AUM_M,0)-NVL(AUM_6M,0),0) AP_AUM_6M_MDIFF
        , ROUND(NVL(AUM_M,0)-NVL(AUM_12M,0),0) AP_AUM_12M_MDIFF
        , ROUND(CASE WHEN NVL(AUM_L,0)>0 THEN (NVL(AUM_M,0)/NVL(AUM_L,0))-1 ELSE 0 END,4) AP_AUM_M_RDIFF
        , ROUND(CASE WHEN NVL(AUM_3M,0)>0 THEN (NVL(AUM_M,0)/NVL(AUM_3M,0))-1 ELSE 0 END,4) AP_AUM_3M_RDIFF
        , ROUND(CASE WHEN NVL(AUM_6M,0)>0 THEN (NVL(AUM_M,0)/NVL(AUM_6M,0))-1 ELSE 0 END,4) AP_AUM_6M_RDIFF
        , ROUND(CASE WHEN NVL(AUM_12M,0)>0 THEN (NVL(AUM_M,0)/NVL(AUM_12M,0))-1 ELSE 0 END,4) AP_AUM_12M_RDIFF
        
        , ROUND(NVL(台股庫存M,0),0) ST_AUM_M
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 THEN NVL(台股庫存M,0)/NVL(AUM_M,0) ELSE 0 END,4) ST_AUM_M_RATIO
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_L,0)>0 THEN (NVL(台股庫存M,0)/NVL(AUM_M,0)-NVL(台股庫存L,0)/NVL(AUM_L,0)) ELSE 0 END,4) ST_AUM_M_RATIO_MDIFF
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_3M,0)>0 THEN (NVL(台股庫存M,0)/NVL(AUM_M,0)-NVL(台股庫存3M,0)/NVL(AUM_3M,0)) ELSE 0 END,4) ST_AUM_3M_RATIO_MDIFF
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_6M,0)>0 THEN (NVL(台股庫存M,0)/NVL(AUM_M,0)-NVL(台股庫存6M,0)/NVL(AUM_6M,0)) ELSE 0 END,4) ST_AUM_6M_RATIO_MDIFF
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_12M,0)>0 THEN (NVL(台股庫存M,0)/NVL(AUM_M,0)-NVL(台股庫存12M,0)/NVL(AUM_12M,0)) ELSE 0 END,4) ST_AUM_12M_RATIO_MDIFF
        , ROUND(NVL(台股庫存M,0)-NVL(台股庫存L,0),0) ST_AUM_M_MDIFF
        , ROUND(NVL(台股庫存M,0)-NVL(台股庫存3M,0),0) ST_AUM_3M_MDIFF
        , ROUND(NVL(台股庫存M,0)-NVL(台股庫存6M,0),0) ST_AUM_6M_MDIFF
        , ROUND(NVL(台股庫存M,0)-NVL(台股庫存12M,0),0) ST_AUM_12M_MDIFF
        , ROUND(CASE WHEN NVL(台股庫存L,0)>0 THEN (NVL(台股庫存M,0)/NVL(台股庫存L,0))-1 ELSE 0 END,4) ST_AUM_M_RDIFF
        , ROUND(CASE WHEN NVL(台股庫存3M,0)>0 THEN (NVL(台股庫存M,0)/NVL(台股庫存3M,0))-1 ELSE 0 END,4) ST_AUM_3M_RDIFF
        , ROUND(CASE WHEN NVL(台股庫存6M,0)>0 THEN (NVL(台股庫存M,0)/NVL(台股庫存6M,0))-1 ELSE 0 END,4) ST_AUM_6M_RDIFF
        , ROUND(CASE WHEN NVL(台股庫存12M,0)>0 THEN (NVL(台股庫存M,0)/NVL(台股庫存12M,0))-1 ELSE 0 END,4) ST_AUM_12M_RDIFF
        
        , ROUND(NVL(融資庫存M,0),0) STMT_AUM_M
