        , ROUND(NVL(基金庫存M,0)-NVL(基金庫存12M,0),0) FD_AUM_12M_MDIFF
        , ROUND(CASE WHEN NVL(基金庫存L,0)>0 THEN (NVL(基金庫存M,0)/NVL(基金庫存L,0))-1 ELSE 0 END,4) FD_AUM_M_RDIFF
        , ROUND(CASE WHEN NVL(基金庫存3M,0)>0 THEN (NVL(基金庫存M,0)/NVL(基金庫存3M,0))-1 ELSE 0 END,4) FD_AUM_3M_RDIFF
        , ROUND(CASE WHEN NVL(基金庫存6M,0)>0 THEN (NVL(基金庫存M,0)/NVL(基金庫存6M,0))-1 ELSE 0 END,4) FD_AUM_6M_RDIFF
        , ROUND(CASE WHEN NVL(基金庫存12M,0)>0 THEN (NVL(基金庫存M,0)/NVL(基金庫存12M,0))-1 ELSE 0 END,4) FD_AUM_12M_RDIFF
        
        , ROUND(NVL(結構型商品庫存M,0),0) SN_AUM_M
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 THEN NVL(結構型商品庫存M,0)/NVL(AUM_M,0) ELSE 0 END,4) SN_AUM_M_RATIO
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_L,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(AUM_M,0)-NVL(結構型商品庫存L,0)/NVL(AUM_L,0)) ELSE 0 END,4) SN_AUM_M_RATIO_MDIFF
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_3M,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(AUM_M,0)-NVL(結構型商品庫存3M,0)/NVL(AUM_3M,0)) ELSE 0 END,4) SN_AUM_3M_RATIO_MDIFF
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_6M,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(AUM_M,0)-NVL(結構型商品庫存6M,0)/NVL(AUM_6M,0)) ELSE 0 END,4) SN_AUM_6M_RATIO_MDIFF
        , ROUND(CASE WHEN NVL(AUM_M,0)>0 AND NVL(AUM_12M,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(AUM_M,0)-NVL(結構型商品庫存12M,0)/NVL(AUM_12M,0)) ELSE 0 END,4) SN_AUM_12M_RATIO_MDIFF
        , ROUND(NVL(結構型商品庫存M,0)-NVL(結構型商品庫存L,0),0) SN_AUM_M_MDIFF
        , ROUND(NVL(結構型商品庫存M,0)-NVL(結構型商品庫存3M,0),0) SN_AUM_3M_MDIFF
        , ROUND(NVL(結構型商品庫存M,0)-NVL(結構型商品庫存6M,0),0) SN_AUM_6M_MDIFF
        , ROUND(NVL(結構型商品庫存M,0)-NVL(結構型商品庫存12M,0),0) SN_AUM_12M_MDIFF
        , ROUND(CASE WHEN NVL(結構型商品庫存L,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(結構型商品庫存L,0))-1 ELSE 0 END,4) SN_AUM_M_RDIFF
        , ROUND(CASE WHEN NVL(結構型商品庫存3M,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(結構型商品庫存3M,0))-1 ELSE 0 END,4) SN_AUM_3M_RDIFF
        , ROUND(CASE WHEN NVL(結構型商品庫存6M,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(結構型商品庫存6M,0))-1 ELSE 0 END,4) SN_AUM_6M_RDIFF
        , ROUND(CASE WHEN NVL(結構型商品庫存12M,0)>0 THEN (NVL(結構型商品庫存M,0)/NVL(結構型商品庫存12M,0))-1 ELSE 0 END,4) SN_AUM_12M_RDIFF
        
        , ROUND(NVL(期貨庫存M,0),0) FU_AUM_M
        , ROUND(NVL(期貨庫存M,0)-NVL(期貨庫存L,0),0) FU_AUM_M_MDIFF
        , ROUND(NVL(期貨庫存M,0)-NVL(期貨庫存3M,0),0) FU_AUM_3M_MDIFF
        , ROUND(NVL(期貨庫存M,0)-NVL(期貨庫存6M,0),0) FU_AUM_6M_MDIFF
        , ROUND(NVL(期貨庫存M,0)-NVL(期貨庫存12M,0),0) FU_AUM_12M_MDIFF
        , ROUND(CASE WHEN NVL(期貨庫存L,0)>0 THEN (NVL(期貨庫存M,0)/NVL(期貨庫存L,0))-1 ELSE 0 END,4) FU_AUM_M_RDIFF
        , ROUND(CASE WHEN NVL(期貨庫存3M,0)>0 THEN (NVL(期貨庫存M,0)/NVL(期貨庫存3M,0))-1 ELSE 0 END,4) FU_AUM_3M_RDIFF
        , ROUND(CASE WHEN NVL(期貨庫存6M,0)>0 THEN (NVL(期貨庫存M,0)/NVL(期貨庫存6M,0))-1 ELSE 0 END,4) FU_AUM_6M_RDIFF
        , ROUND(CASE WHEN NVL(期貨庫存12M,0)>0 THEN (NVL(期貨庫存M,0)/NVL(期貨庫存12M,0))-1 ELSE 0 END,4) FU_AUM_12M_RDIFF
FROM TEMP_2AUM1
ORDER BY CUSTOMER_ID
;
INSERT INTO DS_SEC.CF_PROFILE 
SELECT A.CUSTOMER_ID,
    A.YYYYMM,
    GENDER_CODE,
    AGE,
    EDU_DESC,
    POSTAL_RSD_CODE,
    POSTAL_HH_CODE,
    USE_FUBON_ACCT,
    AML_HIGHRISK_FLAG,
    NW_SEGMENT_DESC,
    SEGMENT_DESC,
    VALID_FLAG,
    E_ACCT_VALID_FLAG,
    EMP_FLAG,
    PRO_INVEST_FLAG,
    AML_RISK_DESC,
    KYC_RISK_DESC,
    EMAIL_FLAG,
    LINE_BC_FLAG,
    YEARS_FROM_OPEN,
    MONTHS_FROM_LAST_TXN,
    C_ACCT_VALID_FLAG,
    SUBBROK_ACCT_OPEN_FLAG,
    FUTURE_ACCT_OPEN_FLAG,
    TRUST_ACCT_OPEN_FLAG
FROM DS_SEC.CF_CUSTID A
LEFT JOIN(
    SELECT
    --1. 相對不會隨時間改變資訊
        A.PARTY_ID AS CUSTOMER_ID ,
        A.GENDER_CODE,
        A.AGE,
        A.EDU_DESC,
        --E.OCCU_DESC, --目前還是null值 未來解除遮罩後再重新加入
        A.POSTAL_RSD_CODE,
        A.POSTAL_HH_CODE,
        C.USE_FUBON_ACCT,
        A.AML_HIGHRISK_FLAG,
        C.NW_SEGMENT_DESC,
        C.SEGMENT_DESC,
    --2. 隨時間改變資訊，且可取T_DR_CUST_REL_SEG為資料源，可記錄各月數值
        D.VALID_FLAG,
        D.E_ACCT_VALID_FLAG,
        D.EMP_FLAG,
        D.PRO_INVEST_FLAG,
        D.AML_RISK_DESC,
        D.KYC_RISK_DESC,
        D.EMAIL_FLAG,
        D.LINE_BC_FLAG,
        D.YEARS_FROM_OPEN,
        D.MONTHS_FROM_LAST_TXN,    
    --3. 隨時間改變資訊
        C.C_ACCT_VALID_FLAG,
        C.SUBBROK_ACCT_OPEN_FLAG,
        C.FUTURE_ACCT_OPEN_FLAG,
        C.TRUST_ACCT_OPEN_FLAG
    FROM(
        SELECT PARTY_ID_MASK AS PARTY_ID,GENDER_CODE,AGE,EDU_DESC,
        POSTAL_RSD_CODE,POSTAL_HH_CODE,
        CUST_TYPE_CODE,
        AML_HIGHRISK_FLAG
        FROM DM_S_VIEW.M_PT_CUSTOMER A  --current檔
        INNER JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT WHERE ACCT_VALID_FLAG = 'Y') B
        ON A.PARTY_ID = B.PARTY_ID 
        WHERE CUST_TYPE_CODE ='001'
    )A
    LEFT JOIN (
        SELECT PARTY_ID_MASK AS PARTY_ID,
            MAX(E_ACCT_VALID_FLAG) E_ACCT_VALID_FLAG,
            MAX(C_ACCT_VALID_FLAG) C_ACCT_VALID_FLAG,
            MIN(CASE WHEN NW_SEGMENT_DESC LIKE ('%富裕%') THEN '01.富裕客戶' 
                         WHEN NW_SEGMENT_DESC LIKE ('%價值%') THEN '02.價值客戶'
                         WHEN NW_SEGMENT_DESC LIKE ('%潛力%') THEN '03.潛力客戶'
                         ELSE NW_SEGMENT_DESC
                         END ) NW_SEGMENT_DESC,
            MIN(CASE WHEN SEGMENT_DESC LIKE ('%富裕%') THEN '01.富裕客戶' 
                         WHEN SEGMENT_DESC LIKE ('%價值%') THEN '02.價值客戶'
                         WHEN SEGMENT_DESC LIKE ('%潛力%') THEN '03.潛力客戶'
                         ELSE SEGMENT_DESC
                         END ) SEGMENT_DESC,
            MAX(CASE WHEN BANK_DESC = '台北富邦商業銀行' THEN 'Y' ELSE 'N' END) USE_FUBON_ACCT,
            DECODE(MAX(CASE WHEN PROD_TYPE_CODE='200' AND ACCT_VALID_FLAG='Y' THEN 2 
                          WHEN PROD_TYPE_CODE='200' THEN 1
                          ELSE 0 END),2,'有效戶',1,'曾為有效戶',0,'未開戶') SUBBROK_ACCT_OPEN_FLAG, --有複委託帳號註記
            DECODE(MAX(CASE WHEN PROD_TYPE_CODE='300' AND ACCT_VALID_FLAG='Y' THEN 2 
                          WHEN PROD_TYPE_CODE='300' THEN 1
                          ELSE 0 END),2,'有效戶',1,'曾為有效戶',0,'未開戶') FUTURE_ACCT_OPEN_FLAG, --有期貨帳號註記
            DECODE(MAX(CASE WHEN PROD_TYPE_CODE='400' AND ACCT_VALID_FLAG='Y' THEN 2 
                          WHEN PROD_TYPE_CODE='400' THEN 1
                          ELSE 0 END),2,'有效戶',1,'曾為有效戶',0,'未開戶') TRUST_ACCT_OPEN_FLAG --有信託帳號註記
        FROM DM_S_VIEW.M_AC_ACCOUNT --current檔
        GROUP BY PARTY_ID_MASK 
    ) C ON A.PARTY_ID=C.PARTY_ID
    LEFT JOIN (
        SELECT PARTY_ID_MASK AS PARTY_ID,
            SNAP_YYYYMM,
            VALID_FLAG,
            E_ACCT_VALID_FLAG,
            EMP_FLAG,
            PRO_INVEST_FLAG,
            AML_RISK_DESC,
            KYC_RISK_DESC,
            EMAIL_FLAG,
            LINE_BC_FLAG,
            YEARS_FROM_OPEN,
            MONTHS_FROM_LAST_TXN
        FROM DM_S_VIEW.T_DR_CUST_REL_SEG A
        INNER JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) B
        ON A.PARTY_ID = B.PARTY_ID 
        WHERE SNAP_YYYYMM=:ym  and VALID_FLAG = 'Y'
    ) D ON A.PARTY_ID=D.PARTY_ID
    LEFT JOIN (
        SELECT PARTY_ID, OCCU_DESC
        FROM(
            SELECT PARTY_ID_MASK AS PARTY_ID,B.OPEN_DATE, A.OCCU_DESC,
            ROW_NUMBER() OVER (PARTITION BY PARTY_ID_MASK ORDER BY B.OPEN_DATE DESC) AS RANK_
            FROM DM_S_VIEW.M_AC_ACCOUNT_INFO A  --current檔
            LEFT JOIN DM_S_VIEW.M_AC_ACCOUNT B  --current檔
            ON A.SNAP_YYYYMM=B.SNAP_YYYYMM AND A.ACCT_NBR=B.ACCT_NBR AND A.PROD_TYPE_CODE=B.PROD_TYPE_CODE
            WHERE OPEN_DATE IS NOT NULL
        ) WHERE RANK_ = 1
    )E ON A.PARTY_ID=E.PARTY_ID
)B ON A.CUSTOMER_ID  = B.CUSTOMER_ID  
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID
;
/*******************************************************************************************/

